window.PREP_PROSE = {
"oxygen":{"apparatus":["大试管","单孔橡胶塞与导管","集气瓶","水槽","酒精灯","铁架台","棉花"],"observation":"紫黑色高锰酸钾逐渐变为黑色固体，导管口连续放出气泡；带火星木条在氧气中复燃，燃烧明显变旺。","cautions":["试管口的棉花不可塞紧，否则气体无法排出、装置内压强过大可能冲开塞子。","必须先撤导管后熄灯，否则水会倒吸进热试管使其炸裂。","氯酸钾与可燃物（如硫、红磷、炭粉）混合后受热或研磨可能爆炸，绝不能混合研磨。","过氧化氢具有腐蚀性，30% 溶液接触皮肤会发白灼痛，需戴手套。"],"conclusion":"加热高锰酸钾分解制氧是实验室最简便的方法；棉花可防止粉末堵塞导管。"},
"carbon-dioxide":{"apparatus":["锥形瓶","长颈漏斗","双孔橡胶塞","导管","集气瓶","燃着的木条"],"observation":"大理石表面产生大量气泡，固体逐渐溶解；澄清石灰水先变浑浊。","cautions":["不用稀硫酸：生成的硫酸钙微溶，覆盖在碳酸钙表面阻止反应继续进行。","不用浓盐酸：氯化氢挥发混入气体，使收集到的二氧化碳不纯。","不用碳酸钠粉末：反应过快，不易控制气流。","二氧化碳不支持呼吸，制取与收集应在通风处进行，切勿在密闭空间大量制备。"],"conclusion":"碳酸钙与盐酸反应速率适中，适合常规制备；盐酸挥发性使气体需经纯化。"},
"hydrogen":{"apparatus":["启普发生器或简易气体发生装置","集气瓶","水槽","尖嘴导管"],"observation":"锌粒表面持续冒出气泡；纯氢安静燃烧，火焰呈淡蓝色，在火焰上方罩干冷烧杯内壁出现水雾。","cautions":["点燃氢气前必须验纯。氢气与空气混合达到爆炸极限（约 4%–75%）时遇明火会剧烈爆炸。","实验区域严禁明火，装置不能漏气。","不用浓硫酸（反应慢且可能产生二氧化硫）、不用硝酸（具有氧化性，不放出氢气）。","启普发生器使用前要检查导气旋塞，停止反应时先关旋塞再关热源。"],"conclusion":"锌与稀硫酸反应平稳，氢气纯度依赖排空气与验纯操作。"},
"chlorine":{"apparatus":["圆底烧瓶","分液漏斗","酒精灯","洗气瓶","集气瓶","尾气吸收装置"],"observation":"烧瓶内产生黄绿色气体，有强烈刺激性气味；湿润淀粉碘化钾试纸变蓝；集气瓶中气体呈黄绿色。","cautions":["氯气剧毒，吸入可致肺水肿。全程必须在通风橱内操作，佩戴防毒面具与护目镜。","尾气必须用碱液吸收，严禁排入室内或下水道。","氯气与氢气混合见光即爆炸，二者不得在同一区域同时制备。","本实验属于高危演示，学生不得自行制备，学校须由教师演示并报备。"],"conclusion":"浓盐酸与二氧化锰需加热才能持续反应；尾气必须用碱液吸收。"},
"ammonia":{"apparatus":["大试管","酒精灯","干燥管","集气瓶","玻璃棒"],"observation":"产生有刺激性气味的气体；湿润红色石蕊试纸变蓝；遇浓盐酸产生白烟。","cautions":["不能用无水氯化钙干燥氨气，二者会生成 CaCl₂·8NH₃。","氨气有刺激性，操作应在通风处进行，避免直接吸入。","加热时试管口略向下倾斜，防止冷凝水倒流炸裂试管。","收集满后应立即用塞子塞紧，氨气易扩散。"],"conclusion":"固体氢氧化钙与氯化铵共热是实验室制氨的经典方法，收集需向下排空气。"},
"copper-sulfate":{"apparatus":["烧杯","玻璃棒","蒸发皿","漏斗","结晶皿","抽滤装置"],"observation":"蓝色溶液；冷却后析出深蓝色棱柱状晶体；晶体受热逐渐变白（失去结晶水）。","cautions":["蒸发浓缩不能蒸干，否则硫酸铜会分解并夹杂杂质。","胆矾在干燥空气中会缓慢风化，应密封保存。","滤液含铜离子，属重金属废水，必须回收处理，不得倒入下水道。","浓硫酸稀释时要把酸加入水中，并不断搅拌。"],"conclusion":"铜与浓硫酸反应需加热，产物经浓缩结晶可得五水合硫酸铜。"},
"feoh3-colloid":{"apparatus":["小烧杯","酒精灯","石棉网","胶头滴管","激光笔"],"observation":"液体呈红褐色、透明；激光照射出现明显的丁达尔效应光路；久置或加入电解质后产生红褐色沉淀。","cautions":["不能用氢氧化钠溶液代替水，否则直接生成 Fe(OH)₃ 沉淀而非胶体。","加热过程中不要搅拌，也不要长时间煮沸，否则胶体聚沉。","胶体制好后不能过滤，胶体粒子可以透过滤纸。","氯化铁溶液呈酸性，避免接触衣物。"],"conclusion":"饱和氯化铁滴入沸水水解可得红褐色氢氧化铁胶体，可用于丁达尔效应演示。"},
"ethyl-acetate":{"apparatus":["大试管","导管","酒精灯","试管夹","量筒"],"observation":"有果香味逸出；饱和碳酸钠溶液上层出现无色透明油状液体，下层溶液仍澄清。","cautions":["加料顺序为乙醇 → 浓硫酸 → 乙酸，绝不能先混合浓硫酸与乙酸再倒回乙醇。","导管末端不能插入液面下，防止受热不均造成倒吸。","必须小火加热：温度过高会使乙酸乙酯挥发损失并导致炭化。","浓硫酸有强腐蚀性；乙酸有刺激性气味，操作时注意通风。"],"conclusion":"乙酸与乙醇在浓硫酸催化下酯化，收集馏出液即得乙酸乙酯。"},
"soap":{"apparatus":["烧杯","玻璃棒","水浴锅","纱布","模具"],"observation":"反应液逐渐变稠；盐析后上层析出白色或淡黄色固体；成品肥皂溶于水后起泡。","cautions":["氢氧化钠有强腐蚀性，必须戴手套和护目镜。","乙醇易燃，只能水浴加热，不可用明火直接加热。","盐析必须用饱和食盐水，浓度不足时肥皂不能充分析出。","皂化不完全的产物碱性过强，不能直接用于皮肤。"],"conclusion":"油脂在碱液中水解生成高级脂肪酸盐，盐析后析出肥皂。"},
"aspirin":{"apparatus":["干燥锥形瓶","水浴锅","温度计","抽滤装置","表面皿"],"observation":"反应液逐渐变澄清；冷却后析出白色晶体；用三氯化铁溶液检验，纯品不显紫色（酚羟基已被酰化）。","cautions":["乙酸酐有强腐蚀性和刺激性，遇水剧烈水解，操作须在通风橱内并戴手套。","水浴温度不要超过 85 ℃，温度过高会促进副产物生成并使产品发黄。","浓硫酸催化，滴加时避免接触皮肤。","阿司匹林是药物，本实验产物只能用于教学检验，不可服用。"],"conclusion":"水杨酸与乙酸酐在酸催化下乙酰化，冰水浴使阿司匹林结晶析出。"},
"mohr-salt":{"apparatus":["锥形瓶","水浴锅","漏斗","蒸发皿","抽滤装置"],"observation":"溶液呈浅绿色；冷却后析出浅绿色晶体；晶体久置表面可能泛黄（被氧化）。","cautions":["亚铁离子易被空气氧化，制备过程要快、要加铁粉、避免长时间暴露。","浓缩时不能蒸干，否则硫酸亚铁铵会分解。","产品应密封避光保存，防止风化与氧化。","稀硫酸有腐蚀性，加热时注意防止暴沸。"],"conclusion":"硫酸亚铁与硫酸铵混合溶液结晶可得摩尔盐，其稳定性优于硫酸亚铁。"},
"silver-ammonia":{"apparatus":["洁净试管","胶头滴管","试管架"],"observation":"先出现棕褐色氢氧化银（迅速分解为氧化银）沉淀，继续加氨水后沉淀溶解，得到无色透明溶液。","cautions":["必须现配现用。久置或蒸干会生成雷爆银（Ag₃N），受摩擦、受热即剧烈爆炸。","配制时氨水绝不能过量，沉淀刚好溶解即停。","残液与含银废液统一回收，由实验员当日处理，严禁倒入水槽或久置。","所有含银废液统一回收，不得排入下水道。"],"conclusion":"硝酸银与氨水配位生成银氨溶液，需现配现用，久置可能生成爆炸性氮化银。"},
"indicators":{"apparatus":["小烧杯","玻璃棒","100 mL 容量瓶","棕色滴瓶"],"observation":"酚酞在碱性溶液中呈粉红至红色，遇酸褪为无色；甲基橙在酸性中红、中性橙、碱性黄。","cautions":["乙醇易燃，配制时远离明火。","指示剂应避光保存，久置会变质导致变色不敏锐。","变色范围受温度影响，精密滴定需做空白对照。"],"conclusion":"紫甘蓝花青素与酚酞在不同 pH 下结构变化，颜色可指示酸碱范围。"},
"iodine-solution":{"apparatus":["烧杯","玻璃棒","棕色试剂瓶","天平"],"observation":"得到棕褐色溶液；滴入淀粉溶液立即变深蓝。","cautions":["碘有腐蚀性且易升华，称量时动作要快，避免吸入蒸气。","不能直接把碘加入水中，几乎不溶。","碘液应避光密封保存，避免与还原性物质接触。"],"conclusion":"碘在碘化钾溶液中以三碘配离子形式溶解，得到稳定的棕黄色碘液。"},
"sodium-chloride":{"apparatus":["烧杯","滴定管","蒸发皿","酒精灯","玻璃棒"],"observation":"终点时红色突然褪去；蒸发后析出白色立方晶体。","conclusion":"强酸与强碱中和生成盐和水；NaCl 溶解度随温度变化小，适合蒸发结晶。","cautions":["盐酸和氢氧化钠均有腐蚀性，佩戴护目镜。","蒸发时不可蒸干，以免暴沸。"]},
"potassium-chloride":{"apparatus":["烧杯","滴定管","蒸发皿","酒精灯"],"observation":"无色溶液，蒸发后得到白色晶体。","conclusion":"中和反应可用于制备可溶性盐；KCl 溶解度随温度升高明显增大，也可用冷却结晶。","cautions":["氢氧化钾腐蚀性强，避免接触皮肤。","稀释或中和会放热，必须由实验员操作，缓慢加入并搅拌。"]},
"calcium-chloride":{"apparatus":["锥形瓶","长颈漏斗","蒸发皿","酒精灯","漏斗"],"observation":"固体表面持续冒出气泡，反应放热；浓缩后析出无色晶体。","conclusion":"碳酸盐与酸反应放出二氧化碳；氯化钙易潮解，应密封保存。","cautions":["二氧化碳逸出快，注意排气。","氯化钙结晶水合物加热易失去结晶水。"]},
"magnesium-chloride":{"apparatus":["烧杯","蒸发皿","酒精灯","漏斗"],"observation":"白色粉末溶解，溶液澄清；冷却后析出针状晶体。","conclusion":"碱性氧化物与酸反应生成盐；MgCl₂·6H₂O 易潮解。","cautions":["浓缩时避免局部过热。","晶体应密封保存。"]},
"ammonium-chloride":{"apparatus":["烧杯","滴定管","蒸发皿","酒精灯","通风橱"],"observation":"加酸后碱性减弱，指示剂由黄变橙；蒸发时闻到微弱氨味。","conclusion":"弱碱与强酸中和生成盐；NH₄Cl 受热易分解，蒸发不宜过干。","cautions":["氨水有刺激性气味，操作在通风橱中进行。","避免与碱共热，防止放出氨气。"]},
"ferrous-chloride":{"apparatus":["锥形瓶","漏斗","蒸发皿","水浴","棕色瓶"],"observation":"铁屑表面产生气泡，溶液呈浅绿色；久置后颜色变黄。","conclusion":"铁与非氧化性酸反应生成亚铁盐；Fe²⁺ 易被氧化，需过量铁和密封保存。","cautions":["氢气可燃，远离火源。","亚铁盐溶液现配现用，防止氧化。"]},
"ferric-chloride":{"apparatus":["烧杯","蒸发皿","水浴","漏斗"],"observation":"溶液呈棕黄色；冷却后析出橙黄色晶体。","conclusion":"Fe³⁺ 水解显酸性，加盐酸可抑制水解；氯化铁易潮解。","cautions":["盐酸具有腐蚀性。","氯化铁溶液对织物和皮肤有染色性。"]},
"aluminium-chloride":{"apparatus":["烧杯","蒸发皿","水浴","漏斗"],"observation":"白色固体溶解，溶液澄清；冷却析出无色晶体。","conclusion":"两性氧化物可溶于强酸；AlCl₃ 易水解，无水物需在干燥氯化氢气流中加热。","cautions":["氯化铝水解产生酸性气体，注意通风。","晶体易潮解，密封保存。"]},
"ferrous-sulfate":{"apparatus":["锥形瓶","漏斗","蒸发皿","水浴","棕色瓶"],"observation":"产生无色气泡，溶液呈浅绿色；冷却后析出绿色晶体。","conclusion":"铁与稀硫酸发生置换反应；绿矾在空气中易风化、氧化。","cautions":["氢气易燃，操作远离明火。","绿矾应密封避光保存。"]},
"zinc-sulfate":{"apparatus":["锥形瓶","漏斗","蒸发皿","水浴"],"observation":"锌粒表面产生气泡，溶液无色；冷却析出无色晶体。","conclusion":"活泼金属与稀酸置换出氢；ZnSO₄·7H₂O 俗称皓矾。","cautions":["氢气易燃，远离火源。","锌盐溶液不可随意排放。"]},
"magnesium-sulfate":{"apparatus":["烧杯","蒸发皿","水浴","漏斗"],"observation":"白色粉末溶解，溶液澄清；冷却析出针状晶体。","conclusion":"碱性氧化物与酸反应生成盐；MgSO₄·7H₂O 俗称泻盐。","cautions":["浓缩时控制温度，避免晶体发黄。","产品密封防潮。"]},
"aluminium-sulfate":{"apparatus":["烧杯","蒸发皿","水浴","漏斗"],"observation":"白色胶状固体溶解，溶液澄清；冷却后析出白色晶体。","conclusion":"两性氢氧化物可溶于酸；硫酸铝易水解，水溶液显酸性。","cautions":["氢氧化铝制备时避免过量碱导致溶解。","产品密封防潮。"]},
"ferric-sulfate":{"apparatus":["烧杯","蒸发皿","水浴","漏斗"],"observation":"红棕色固体溶解，溶液呈黄色；浓缩后析出淡黄色晶体。","conclusion":"铁盐溶液显黄色；硫酸铁易水解，浓缩时保持酸性。","cautions":["硫酸铁溶液对皮肤有刺激性。","避免与还原性物质混合。"]},
"ammonium-sulfate":{"apparatus":["烧杯","滴定管","蒸发皿","水浴","通风橱"],"observation":"中和时放热，溶液由碱性变为近中性；蒸发得白色晶体。","conclusion":"弱碱与强酸中和生成铵盐；硫酸铵是常见氮肥。","cautions":["氨水有刺激性，在通风橱中操作。","铵盐避免与碱共热。"]},
"sodium-sulfate":{"apparatus":["烧杯","滴定管","蒸发皿","水浴"],"observation":"中和后溶液无色；冷却析出大块无色晶体。","conclusion":"Na₂SO₄·10H₂O 即芒硝，溶解度随温度变化较大，适合冷却结晶。","cautions":["氢氧化钠腐蚀性强。","芒硝在干燥空气中易风化。"]},
"sodium-bisulfate":{"apparatus":["蒸馏烧瓶","温度计","导管","蒸发皿","通风橱"],"observation":"有刺激性气体放出，用湿润蓝色石蕊试纸变红；残留物冷却后为白色固体。","conclusion":"高沸点酸可制低沸点酸；控制温度可停留在酸式盐阶段。","cautions":["氯化氢气体有毒且腐蚀，必须在通风橱中操作并吸收尾气。","浓硫酸强腐蚀，缓慢加入并搅拌。"]},
"barium-sulfate":{"apparatus":["烧杯","漏斗","抽滤瓶","干燥器"],"observation":"立即生成白色细沉淀，静置后沉降。","conclusion":"难溶电解质通过复分解反应制备；洗涤可除去可溶性杂质。","cautions":["可溶性钡盐有毒，避免吸入或误食。","废液含钡离子，需专门处理。"]},
"calcium-sulfate":{"apparatus":["烧杯","漏斗","干燥器"],"observation":"生成白色沉淀，料浆略显粘稠。","conclusion":"硫酸钙微溶，复分解可制得石膏；加热失水可制熟石膏。","cautions":["硫酸钙粉尘刺激呼吸道。","洗涤要充分，避免夹带氯化钠。"]},
"potassium-nitrate":{"apparatus":["烧杯","加热套","冰水浴","漏斗","抽滤瓶"],"observation":"加热后溶液澄清；冷却后析出针状或柱状晶体。","conclusion":"利用 KNO₃ 溶解度随温度变化大、NaCl 变化小的差异分离盐类。","cautions":["硝酸钾是强氧化剂，远离可燃物和还原剂。","高温操作防止烫伤。"]},
"sodium-nitrate":{"apparatus":["烧杯","蒸发皿","水浴","pH 试纸"],"observation":"固体溶解并放出气泡；浓缩后析出白色晶体。","conclusion":"碳酸盐与酸反应生成盐、水和二氧化碳；硝酸钠是强氧化剂。","cautions":["硝酸具有腐蚀性，操作佩戴护目镜。","硝酸钠受热分解，避免高温加热。"]},
"copper-nitrate":{"apparatus":["烧杯","蒸发皿","水浴","漏斗"],"observation":"黑色固体溶解，溶液呈蓝绿色；冷却析出深蓝色晶体。","conclusion":"碱性氧化物溶于酸生成盐；硝酸铜晶体含三个结晶水。","cautions":["硝酸具有腐蚀性和氧化性。","硝酸铜受热分解，避免高温干燥。"]},
"silver-nitrate":{"apparatus":["锥形瓶","水浴","蒸发皿","棕色瓶","通风橱"],"observation":"银溶解并有红棕色气体产生；浓缩后析出无色片状晶体。","conclusion":"银溶于稀硝酸生成硝酸银；硝酸银见光易分解，须避光保存。","cautions":["氮氧化物有毒，必须在通风橱中操作。","硝酸银对皮肤有腐蚀性和染色性，避免接触。"]},
"sodium-carbonate":{"apparatus":["坩埚","酒精灯","干燥器","天平"],"observation":"加热时产生气体，固体质量减小；产物为白色粉末。","conclusion":"碳酸氢钠热稳定性差，受热分解生成碳酸钠；可用于区别两种碳酸盐。","cautions":["灼烧时用坩埚钳夹取，防止烫伤。","产物冷却后再称量，避免吸潮。"]},
"sodium-bicarbonate":{"apparatus":["锥形瓶","导管","冰水浴","漏斗","抽滤瓶"],"observation":"通入二氧化碳后溶液变浑浊，逐渐析出白色细晶体。","conclusion":"碳酸氢钠溶解度较小，在饱和食盐水中先析出；滤液可回收氯化铵。","cautions":["氨气有刺激性，操作在通风橱中进行。","低温操作可提高产率。"]},
"calcium-carbonate":{"apparatus":["烧杯","漏斗","抽滤瓶","干燥器"],"observation":"立即生成白色沉淀，静置后沉降。","conclusion":"复分解反应可制备难溶碳酸盐；洗涤除去可溶性杂质。","cautions":["沉淀洗涤要充分，避免夹带氯化钠。","干燥温度不宜过高，防止分解。"]},
"magnesium-carbonate":{"apparatus":["烧杯","漏斗","抽滤瓶","干燥器"],"observation":"生成白色胶状沉淀，洗涤后体积缩小。","conclusion":"镁离子与碳酸根生成难溶碳酸盐；实际产物常含碱式碳酸镁。","cautions":["沉淀易胶溶，洗涤时用热水。","干燥温度过高会分解。"]},
"potassium-carbonate":{"apparatus":["锥形瓶","导管","蒸发皿","水浴"],"observation":"通入气体时无明显现象，溶液碱性逐渐减弱。","conclusion":"强碱吸收酸性氧化物生成盐；碳酸钾溶液显碱性。","cautions":["氢氧化钾腐蚀性强。","通气管末端应接近液面但避免倒吸。"]},
"potassium-dihydrogen-phosphate":{"apparatus":["烧杯","pH 计","蒸发皿","水浴"],"observation":"加酸时放出气泡，溶液澄清；冷却析出无色晶体。","conclusion":"酸式盐的制备需控制酸碱比例；KH₂PO₄ 溶液呈弱酸性。","cautions":["磷酸具有腐蚀性，避免接触皮肤。","浓缩时控制温度防止分解。"]},
"sodium-hydrogen-phosphate":{"apparatus":["烧杯","pH 计","蒸发皿","水浴"],"observation":"反应放热，溶液澄清；冷却后析出无色晶体。","conclusion":"控制 pH 可得到不同磷酸盐；磷酸氢二钠溶液呈弱碱性，可作缓冲对。","cautions":["氢氧化钠腐蚀性强，佩戴护目镜。","结晶水合物在干燥空气中易风化。"]},
"sodium-phosphate":{"apparatus":["烧杯","pH 计","蒸发皿","水浴"],"observation":"溶液澄清，冷却后析出白色晶体。","conclusion":"磷酸三钠溶液碱性强，水解程度大。","cautions":["强碱操作注意防护。","产品密封防潮。"]},
"sodium-silicate":{"apparatus":["铁坩埚","酒精喷灯","坩埚钳","防护面罩"],"observation":"高温下物料熔融，冷却后为玻璃状固体，溶于水呈粘稠液。","conclusion":"二氧化硅是酸性氧化物，高温下与强碱反应；产物水玻璃可作粘结剂。","cautions":["高温熔融碱腐蚀性极强，必须佩戴面罩和手套。","操作在通风处进行，避免碱雾。"]},
"sodium-thiosulfate":{"apparatus":["圆底烧瓶","回流冷凝管","漏斗","蒸发皿"],"observation":"回流时淡黄色硫粉逐渐消失，溶液澄清。","conclusion":"亚硫酸盐与硫共热生成硫代硫酸盐；大苏打是常用还原剂和定影剂。","cautions":["加热回流注意防倒吸。","硫粉易燃，远离明火。"]},
"sodium-sulfite":{"apparatus":["锥形瓶","导管","尾气吸收装置","蒸发皿"],"observation":"通入气体时溶液仍澄清，碱性逐渐减弱。","conclusion":"亚硫酸钠易被氧化为硫酸钠，应密封保存。","cautions":["二氧化硫有毒且有刺激性，尾气用碱液吸收。","操作在通风橱中进行。"]},
"potassium-iodide":{"apparatus":["烧杯","水浴","蒸发皿","通风橱"],"observation":"碘溶解后溶液呈棕色，加碱后变浅；加过氧化氢后放出气体。","conclusion":"碘在碱中歧化，再用还原剂把碘酸根还原为碘离子；碘化钾见光易变黄。","cautions":["碘蒸气有刺激性，操作在通风橱中进行。","过氧化氢具有腐蚀性。"]},
"potassium-bromide":{"apparatus":["烧杯","蒸发皿","水浴","漏斗"],"observation":"加酸时放出气泡，溶液澄清；冷却析出无色晶体。","conclusion":"碳酸盐与氢卤酸反应生成卤化物；溴化钾是常用红外窗片材料。","cautions":["氢溴酸具有腐蚀性。","产品密封防潮。"]},
"potassium-permanganate":{"apparatus":["铁坩埚","酒精喷灯","电解装置","防护面罩"],"observation":"熔融物呈绿色；电解后溶液逐渐变为紫红色。","conclusion":"锰的化合价由 +4 升至 +6 再升至 +7；高锰酸钾是强氧化剂。","cautions":["强碱高温熔融极危险，须佩戴面罩和防护手套。","高锰酸钾与有机物混合可能燃烧，不可研磨混存。"]},
"potassium-chlorate":{"apparatus":["烧杯","水浴","尾气吸收装置","通风橱"],"observation":"溶液吸收氯气后变为浅黄绿色，冷却析出白色晶体。","conclusion":"氯气在热碱中歧化生成氯酸盐；氯酸钾是强氧化剂，受热分解。","cautions":["氯气有毒，操作必须在通风橱中进行并吸收尾气。","氯酸钾与硫、磷等还原剂混合受热会爆炸，严禁混存。"]},
"potash-alum":{"apparatus":["烧杯","蒸发皿","水浴","漏斗"],"observation":"混合液澄清，冷却后析出无色八面体晶体。","conclusion":"两种盐按一定比例结晶形成复盐；明矾可作净水剂。","cautions":["硫酸铝溶液有刺激性。","结晶时避免杂质混入。"]},
"silver-chloride":{"apparatus":["烧杯","抽滤瓶","棕色瓶","干燥器"],"observation":"生成白色絮状沉淀，见光逐渐变灰紫色。","conclusion":"氯化银难溶，见光分解；可用于检验氯离子。","cautions":["硝酸银腐蚀皮肤，避免接触。","沉淀及废液需回收，不可随意排放。"]},
"ferrous-sulfide":{"apparatus":["试管","酒精灯","坩埚钳","通风橱"],"observation":"混合物红热，生成黑色固体，有少量气体逸出。","conclusion":"铁与硫化合生成硫化亚铁；产物不溶于水，溶于稀酸放出硫化氢。","cautions":["反应放热剧烈，试管口不要对人。","硫化氢有毒，后续酸溶操作应在通风橱中进行。"]},
"calcium-oxide":{"apparatus":["坩埚","酒精喷灯","坩埚钳","干燥器"],"observation":"白色固体变为疏松的白色块状物，质量减小。","conclusion":"碳酸盐高温分解生成氧化物；生石灰遇水放热生成熟石灰。","cautions":["高温操作戴护目镜和手套。","生石灰遇水剧烈放热，避免接触皮肤。"]},
"magnesium-oxide":{"apparatus":["坩埚","酒精喷灯","天平","干燥器"],"observation":"白色粉末逐渐变轻，冷却后仍为白色。","conclusion":"镁的碳酸盐受热分解为氧化镁；氧化镁熔点高，可作耐火材料。","cautions":["灼烧后坩埚温度高，用坩埚钳夹取。","氧化镁粉尘刺激呼吸道。"]},
"copper-oxide":{"apparatus":["蒸发皿","酒精灯","玻璃棒","干燥器"],"observation":"蓝色固体逐渐变黑，并有水蒸气逸出。","conclusion":"不溶性氢氧化物受热分解为氧化物；氧化铜可被氢气或碳还原。","cautions":["加热时避免固体飞溅。","氧化铜粉尘有害，操作后洗手。"]},
"ferric-oxide":{"apparatus":["坩埚","酒精灯","干燥器"],"observation":"红褐色胶状沉淀变为红棕色粉末。","conclusion":"氢氧化铁受热分解为氧化铁；氧化铁是红色颜料的主要成分。","cautions":["灼烧时注意通风。","产品密封防潮。"]},
"aluminium-oxide":{"apparatus":["坩埚","酒精喷灯","干燥器"],"observation":"白色胶状固体变为白色疏松粉末。","conclusion":"氢氧化铝灼烧生成两性氧化物氧化铝；氧化铝可作耐火材料和催化剂载体。","cautions":["灼烧时防止粉尘飞扬。","高温坩埚用坩埚钳夹取。"]},
"silica":{"apparatus":["蒸发皿","酒精灯","干燥器"],"observation":"透明凝胶逐渐变为白色固体。","conclusion":"硅酸不稳定，受热脱水生成二氧化硅；二氧化硅是酸性氧化物。","cautions":["二氧化硅粉尘可致硅肺，避免吸入。","加热时防止固体飞溅。"]},
"manganese-dioxide":{"apparatus":["烧杯","水浴","抽滤瓶","干燥器"],"observation":"滴加时生成棕色沉淀，溶液紫红色褪去。","conclusion":"Mn²⁺ 被 MnO₄⁻ 氧化为 MnO₂；二氧化锰可作催化剂和氧化剂。","cautions":["高锰酸钾腐蚀性强，避免接触皮肤。","沉淀洗涤要充分。"]},
"phosphorus-pentoxide":{"apparatus":["燃烧匙","集气瓶","通风橱","防护面罩"],"observation":"红磷剧烈燃烧，发出黄白色光，产生大量白烟。","conclusion":"磷燃烧生成五氧化二磷；P₂O₅ 是强干燥剂，遇水剧烈反应。","cautions":["白烟刺激性极强，必须在通风橱中操作并佩戴面罩。","P₂O₅ 遇水放热，不可直接加水。"]},
"sodium-peroxide":{"apparatus":["坩埚","酒精灯","干燥器","防护面罩"],"observation":"钠先熔化成小球，随后燃烧发出黄色火焰，产物为淡黄色。","conclusion":"钠在氧气中燃烧生成过氧化钠而非氧化钠；Na₂O₂ 与水、二氧化碳反应放出氧气。","cautions":["钠遇水剧烈反应，操作必须干燥。","过氧化钠强氧化性，避免接触可燃物。"]},
"hydrogen-peroxide":{"apparatus":["烧杯","冰水浴","减压蒸馏装置","棕色瓶"],"observation":"反应放热并有少量气泡；浓缩液为无色粘稠液体。","conclusion":"过氧化氢不稳定，受热、见光或遇催化剂易分解；应低温避光保存。","cautions":["高浓度过氧化氢强氧化性，接触皮肤会灼伤。","减压蒸馏防止分解，严禁常压高温浓缩。"]},
"sodium-hydroxide":{"apparatus":["烧杯","漏斗","蒸发皿","铁架台"],"observation":"生成白色沉淀；滤液滑腻，浓缩后为白色固体。","conclusion":"利用溶解度差异制取强碱；氢氧化钠易潮解，须密封保存。","cautions":["氢氧化钠强腐蚀性，佩戴护目镜和手套。","浓缩时防止碱液飞溅。"]},
"potassium-hydroxide":{"apparatus":["烧杯","漏斗","蒸发皿","镍坩埚"],"observation":"白色沉淀生成；滤液浓缩后为白色固体。","conclusion":"钾碱可用苛化法制取；氢氧化钾吸湿性强，腐蚀性强。","cautions":["氢氧化钾强腐蚀，避免接触皮肤和眼睛。","熔融氢氧化钾会腐蚀玻璃，使用镍或银坩埚。"]},
"calcium-hydroxide":{"apparatus":["蒸发皿","玻璃棒","干燥器"],"observation":"剧烈放热，固体膨胀并产生蒸汽，变为白色粉末。","conclusion":"生石灰消化生成熟石灰；氢氧化钙微溶，饱和溶液为石灰水。","cautions":["消化放热剧烈，避免加水过快。","氢氧化钙粉尘刺激皮肤和呼吸道。"]},
"aluminium-hydroxide":{"apparatus":["烧杯","pH 试纸","抽滤瓶","干燥器"],"observation":"生成白色絮状沉淀，洗涤后体积缩小。","conclusion":"用弱碱沉淀铝离子可避免氢氧化铝溶解；氢氧化铝具有两性。","cautions":["氨水有刺激性，操作在通风处进行。","洗涤要充分除去铵盐。"]},
"ferric-hydroxide":{"apparatus":["烧杯","抽滤瓶","干燥器"],"observation":"立即生成红褐色絮状沉淀。","conclusion":"铁离子与碱反应生成难溶氢氧化物；氢氧化铁受热易分解。","cautions":["氢氧化钠腐蚀性强。","沉淀洗涤至滤液中性。"]},
"ferrous-hydroxide":{"apparatus":["试管","长滴管","水浴","氮气或油封"],"observation":"生成白色絮状沉淀，随后迅速变为灰绿色、红褐色。","conclusion":"Fe²⁺ 易被氧化，制备氢氧化亚铁需严格隔绝氧气。","cautions":["煮沸溶液时防止暴沸。","操作要迅速，减少与空气接触。"]},
"copper-hydroxide":{"apparatus":["烧杯","抽滤瓶","干燥器"],"observation":"生成蓝色絮状沉淀。","conclusion":"铜离子与碱反应生成难溶氢氧化铜；该沉淀可检验醛基。","cautions":["硫酸铜溶液有刺激性。","干燥温度不宜超过 60 ℃。"]},
"magnesium-hydroxide":{"apparatus":["烧杯","抽滤瓶","干燥器"],"observation":"生成白色絮状沉淀。","conclusion":"氢氧化镁难溶，可作阻燃剂和中和剂。","cautions":["氢氧化钠腐蚀性强。","沉淀易胶溶，洗涤用热水。"]},
"ammonia-water":{"apparatus":["锥形瓶","导管","冰水浴","通风橱"],"observation":"氨气极易溶解，导管口可能发生倒吸；溶液有刺激性气味。","conclusion":"氨气极易溶于水，溶液显弱碱性；氨水受热易分解放出氨。","cautions":["氨气刺激性强，操作在通风橱中进行。","导管口应接近液面，防止倒吸。"]},
"hydrochloric-acid":{"apparatus":["蒸馏烧瓶","温度计","导管","吸收瓶","通风橱"],"observation":"有白雾状气体逸出，溶于水时放热。","conclusion":"高沸点酸制低沸点酸；氯化氢极易溶于水，需防倒吸。","cautions":["氯化氢气体有毒且腐蚀，必须在通风橱中操作。","浓硫酸强腐蚀，缓慢加入并搅拌。"]},
"nitric-acid":{"apparatus":["蒸馏烧瓶","温度计","冷凝管","接收瓶","通风橱"],"observation":"馏出液无色，久置或见光后逐渐变黄。","conclusion":"高沸点酸制低沸点酸；硝酸见光分解，须避光保存。","cautions":["硝酸强腐蚀性和强氧化性，操作佩戴面罩和手套。","蒸馏装置气密性良好，尾气用碱吸收，全程通风。"]},
"sulfuric-acid":{"apparatus":["燃烧管","接触室","吸收塔","耐酸导管","通风橱"],"observation":"硫燃烧呈蓝紫色火焰；SO₃ 遇水放出大量白雾。","conclusion":"工业制硫酸采用接触法；SO₃ 用水吸收易形成酸雾，故用浓硫酸吸收。","cautions":["SO₂、SO₃ 有毒且腐蚀，全程密闭并通风。","浓硫酸稀释必须酸入水，严禁水入酸。"]},
"phosphoric-acid":{"apparatus":["烧杯","玻璃棒","水浴","通风橱"],"observation":"加入时剧烈放热，有白雾；溶液澄清粘稠。","conclusion":"酸性氧化物与水反应生成酸；磷酸是中强酸，无氧化性。","cautions":["五氧化二磷遇水剧烈放热，分批缓慢加入。","磷酸具有腐蚀性，避免接触皮肤。"]},
"boric-acid":{"apparatus":["烧杯","冰水浴","漏斗","干燥器"],"observation":"冷却后析出白色片状晶体。","conclusion":"硼砂是硼酸的钠盐；硼酸是一元弱酸，可作消毒剂。","cautions":["硼酸对眼睛有刺激性。","洗涤用冰水减少溶解损失。"]},
"silicic-acid":{"apparatus":["烧杯","玻璃棒","漏斗","干燥器"],"observation":"溶液逐渐变稠，形成透明或半透明凝胶。","conclusion":"硅酸是弱酸，溶解度小，易形成胶体；干燥脱水得二氧化硅。","cautions":["盐酸具有腐蚀性。","凝胶洗涤耗时，可多次换水。"]},
"ethylene":{"apparatus":["圆底烧瓶","温度计","导管","水槽","通风橱"],"observation":"反应液变黑并有刺激性气体产生；收集到的气体可燃，火焰明亮。","conclusion":"乙醇在浓硫酸催化下脱水生成乙烯；温度控制是关键副反应的分界。","cautions":["浓硫酸使乙醇碳化，产生 SO₂ 等有毒气体，须通风。","乙烯易燃，远离火源，加热要迅速越过 140 ℃。"]},
"acetylene":{"apparatus":["锥形瓶","分液漏斗","导管","水槽"],"observation":"反应剧烈，有气泡产生，气体燃烧发出明亮火焰并冒黑烟。","conclusion":"电石水解生成乙炔；乙炔含碳量高，燃烧不充分冒黑烟。","cautions":["乙炔易燃易爆，严禁明火，操作区通风。","电石遇水剧烈反应，滴加饱和食盐水可减缓速率。"]},
"methane":{"apparatus":["硬质试管","酒精灯","导管","水槽"],"observation":"混合物逐渐熔化并产生气体，收集到的气体可燃，火焰淡蓝色。","conclusion":"羧酸盐与碱石灰共热脱羧生成烷烃；甲烷是最简单的烷烃。","cautions":["加热时防止试管炸裂，管口略向下倾斜。","甲烷易燃，实验远离明火，结束先撤导管。"]},
"anhydrous-ethanol":{"apparatus":["圆底烧瓶","回流冷凝管","蒸馏装置","干燥管"],"observation":"馏出液澄清，遇水不出现浑浊。","conclusion":"生石灰除去乙醇中的水；无水乙醇沸点 78.3 ℃。","cautions":["乙醇易燃，蒸馏时严禁明火直接加热，用水浴或电热套。","装置必须干燥，防止重新吸水。"]},
"acetaldehyde":{"apparatus":["硬质试管","酒精灯","导管","通风橱"],"observation":"黑色氧化铜变为红色，试管中有刺激性气味液体生成。","conclusion":"乙醇在铜催化下氧化为乙醛；乙醛可发生银镜反应。","cautions":["乙醛有毒且易挥发，操作在通风橱中进行。","乙醇易燃，避免明火。"]},
"acetic-acid":{"apparatus":["三口烧瓶","回流冷凝管","气体导管","蒸馏装置"],"observation":"反应放热，馏出液有强烈酸味。","conclusion":"醛可被氧化为羧酸；乙酸是弱酸，具有刺激性气味。","cautions":["乙醛有毒易燃，氧气与有机物混合有燃爆风险，控制氧浓度。","乙酸腐蚀性强，避免接触皮肤。"]},
"acetone":{"apparatus":["硬质试管","酒精灯","冷凝管","接收瓶"],"observation":"馏出液有特殊气味，与水互溶。","conclusion":"羧酸钙盐干馏生成酮；丙酮是常用有机溶剂。","cautions":["丙酮易燃，操作远离明火。","干馏产生的气体有害，注意通风。"]},
"diethyl-ether":{"apparatus":["圆底烧瓶","温度计","冷凝管","分液漏斗"],"observation":"馏出液有特殊气味，密度小于水，易燃。","conclusion":"乙醇在浓硫酸作用下分子间脱水生成乙醚；温度决定产物。","cautions":["乙醚极易燃、易挥发，且久置生成过氧化物，蒸馏时严禁蒸干。","操作在通风橱中进行，远离明火和静电。"]},
"bromoethane":{"apparatus":["圆底烧瓶","回流冷凝管","蒸馏装置","分液漏斗"],"observation":"馏出液为无色油状液体，密度大于水。","conclusion":"醇与氢卤酸发生取代反应生成卤代烃。","cautions":["氢溴酸和浓硫酸腐蚀性强。","溴乙烷有毒且易燃，操作在通风橱中进行。"]},
"methyl-acetate":{"apparatus":["圆底烧瓶","回流冷凝管","蒸馏装置","分液漏斗"],"observation":"馏出液有水果香味。","conclusion":"羧酸与醇在酸催化下发生酯化反应，产物为酯和水。","cautions":["甲醇有毒，严禁饮用或吸入蒸气。","浓硫酸腐蚀性强，酯化反应需缓慢加热。"]},
"butyl-acetate":{"apparatus":["圆底烧瓶","分水器","回流冷凝管","蒸馏装置"],"observation":"馏出液有梨香味。","conclusion":"酯化反应可逆，用分水器移去水可提高产率。","cautions":["浓硫酸腐蚀性强，混合时缓慢加入。","正丁醇和乙酸丁酯易燃，远离明火。"]},
"ethyl-benzoate":{"apparatus":["圆底烧瓶","回流冷凝管","分液漏斗","蒸馏装置"],"observation":"产物有果香，密度大于水。","conclusion":"芳香酸与醇酯化生成芳香酯；苯甲酸乙酯可作香料。","cautions":["浓硫酸腐蚀性强。","乙醇易燃，回流时注意防火。"]},
"benzoic-acid":{"apparatus":["圆底烧瓶","回流冷凝管","抽滤瓶","冰水浴"],"observation":"回流时溶液由紫红变棕，酸化后析出白色晶体。","conclusion":"苯环侧链烷基被氧化为羧基；苯甲酸是弱酸，可作食品防腐剂。","cautions":["高锰酸钾强氧化性，避免与有机物干混。","甲苯有毒易燃，操作通风并远离火源。"]},
"phenol":{"apparatus":["镍坩埚","酒精喷灯","蒸馏装置","通风橱"],"observation":"酸化后溶液变浑浊，有特殊气味；馏出物冷却为无色晶体。","conclusion":"磺酸盐碱熔可制备酚；苯酚弱酸性，遇三氯化铁显紫色。","cautions":["苯酚有毒且腐蚀皮肤，操作戴手套和护目镜。","熔融碱高温危险，注意防护。"]},
"nitrobenzene":{"apparatus":["三口烧瓶","温度计","回流冷凝管","分液漏斗","通风橱"],"observation":"反应液呈黄色，产物为淡黄色油状液体，有苦杏仁味。","conclusion":"苯环发生亲电取代硝化反应；硝基苯是重要有机中间体。","cautions":["苯有致癌性，硝基苯有毒，全程在通风橱中操作并戴手套。","混酸腐蚀性极强，滴加苯时严格控制温度。"]},
"aniline":{"apparatus":["圆底烧瓶","回流冷凝管","水蒸气蒸馏装置","通风橱"],"observation":"回流时溶液放热；碱化后油状物析出；馏出液有特殊气味。","conclusion":"硝基苯还原生成苯胺；苯胺弱碱性，易被氧化，应避光保存。","cautions":["苯胺剧毒且可经皮肤吸收，必须戴手套并在通风橱中操作。","锡与盐酸产生氢气，远离火源。"]},
"bromobenzene":{"apparatus":["圆底烧瓶","冷凝管","气体吸收装置","分液漏斗","通风橱"],"observation":"反应剧烈，有白雾生成；产物为无色油状液体。","conclusion":"苯在铁催化下发生亲电取代溴代反应；溴苯密度大于水。","cautions":["液溴强腐蚀性和挥发性，操作必须戴防护面罩。","溴化氢有毒，尾气用碱液吸收。"]},
"benzenesulfonic-acid":{"apparatus":["圆底烧瓶","回流冷凝管","水浴","通风橱"],"observation":"反应液逐渐变为均相，冷却后析出针状晶体。","conclusion":"苯环磺化引入磺酸基；苯磺酸强酸性，易吸潮。","cautions":["苯有致癌性，浓硫酸腐蚀性强，全程通风并戴手套。","磺化反应放热，控制加酸速度。"]},
"cyclohexene":{"apparatus":["圆底烧瓶","分馏柱","冷凝管","分液漏斗"],"observation":"馏出液为无色液体，能使溴水褪色。","conclusion":"醇在酸催化下脱水生成烯烃；环己烯含碳碳双键。","cautions":["磷酸腐蚀性较强。","环己烯易燃，蒸馏时远离明火。"]},
"stearic-acid":{"apparatus":["烧杯","水浴","分液漏斗","抽滤瓶"],"observation":"皂化后成粘稠皂液；酸化后析出白色蜡状固体。","conclusion":"油脂碱性水解生成甘油和高级脂肪酸盐；酸化得到游离脂肪酸。","cautions":["氢氧化钠腐蚀性强。","热皂液烫伤风险，操作小心。"]},
"glycerol":{"apparatus":["分液漏斗","减压蒸馏装置","蒸发皿"],"observation":"甘油为无色粘稠液体，味甜，吸湿性强。","conclusion":"甘油是油脂水解的共产物；可与水任意比互溶。","cautions":["减压蒸馏防止甘油高温分解。","甘油高温下可能产生刺激性气体，注意通风。"]},
"urea":{"apparatus":["耐压反应釜","压力表","蒸发皿"],"observation":"产物为白色针状或棱柱状晶体。","conclusion":"尿素是第一个人工合成的有机物；含氮量高，是重要氮肥。","cautions":["高压操作必须使用合格反应釜并由专业人员指导。","氨有刺激性，注意密封和通风。"]},
"citric-acid":{"apparatus":["烧杯","抽滤瓶","蒸发皿","水浴"],"observation":"加石灰乳生成白色沉淀；酸化后溶液澄清，浓缩析出晶体。","conclusion":"利用柠檬酸钙难溶、硫酸钙更难溶实现提取；柠檬酸是三元弱酸。","cautions":["石灰乳强碱性，避免接触皮肤。","稀硫酸具有腐蚀性。"]},
"glucose":{"apparatus":["烧杯","水浴","漏斗","蒸发皿"],"observation":"水解液遇碘不再变蓝；浓缩后析出白色晶体。","conclusion":"多糖在酸催化下水解为单糖；葡萄糖是还原糖。","cautions":["稀硫酸具有腐蚀性。","浓缩时防止局部过热焦化。"]},
"paracetamol":{"apparatus":["锥形瓶","水浴","冰水浴","抽滤瓶"],"observation":"析出白色针状晶体。","conclusion":"氨基乙酰化可降低毒性；对乙酰氨基酚是常用解热镇痛药。","cautions":["乙酸酐具有腐蚀性和刺激性，避免吸入。","对氨基苯酚有毒，操作戴手套。"]},
"methyl-orange-indicator":{"apparatus":["烧杯","玻璃棒","容量瓶","滴管"],"observation":"溶液呈橙色。","conclusion":"指示剂浓度影响变色敏锐度；应避光保存。","cautions":["甲基橙粉尘刺激呼吸道，称量时避免吸入。"]},
"litmus-indicator":{"apparatus":["烧杯","漏斗","滴瓶"],"observation":"提取液呈蓝紫色。","conclusion":"石蕊是从地衣中提取的天然指示剂，变色范围较宽。","cautions":["乙醇易燃，远离明火。","指示剂应避光保存。"]},
"starch-indicator":{"apparatus":["烧杯","玻璃棒","水浴"],"observation":"溶液呈半透明胶状。","conclusion":"淀粉指示剂应在接近终点时加入，防止碘被包裹。","cautions":["煮沸时防止暴沸。","淀粉溶液久置易变质。"]},
"fehling-reagent":{"apparatus":["烧杯","容量瓶","试剂瓶"],"observation":"A 液蓝色，B 液无色；混合后为深蓝色透明液。","conclusion":"斐林试剂可检验还原糖，水浴加热生成砖红色氧化亚铜沉淀。","cautions":["氢氧化钠腐蚀性强。","试剂现配现用，不宜长期保存。"]},
"biuret-reagent":{"apparatus":["烧杯","容量瓶","试剂瓶"],"observation":"A 液无色，B 液蓝色。","conclusion":"双缩脲反应可检验蛋白质或肽键，呈紫色。","cautions":["氢氧化钠腐蚀性强。","B 液不能过量，否则掩盖紫色。"]},
"ninhydrin-reagent":{"apparatus":["烧杯","棕色滴瓶"],"observation":"溶液呈淡黄色。","conclusion":"茚三酮可用于氨基酸的纸层析显色。","cautions":["茚三酮对皮肤有染色性，戴手套操作。","乙醇易燃。"]},
"bromine-water":{"apparatus":["磨口试剂瓶","通风橱","防护面罩"],"observation":"溶液呈橙黄色，有刺激性气味。","conclusion":"溴水可用于检验不饱和键和酚类；浓度不稳定，现配现用。","cautions":["液溴剧毒且强腐蚀，必须佩戴面罩和耐酸手套。","溴蒸气刺激呼吸道，全程通风。"]},
"chlorine-water":{"apparatus":["锥形瓶","导管","棕色瓶","通风橱"],"observation":"溶液呈浅黄绿色，有刺激性气味。","conclusion":"氯水中含 Cl₂、HClO、H⁺、Cl⁻ 等，具有酸性和漂白性。","cautions":["氯气有毒，操作必须在通风橱中进行。","氯水见光分解，不宜久存。"]},
"limewater":{"apparatus":["烧杯","玻璃棒","漏斗","试剂瓶"],"observation":"溶液澄清，久置表面形成白色薄膜。","conclusion":"石灰水用于检验二氧化碳，变浑浊生成碳酸钙。","cautions":["氢氧化钙粉尘刺激皮肤。","应密封保存，防止与二氧化碳反应。"]},
"kscn-solution":{"apparatus":["烧杯","容量瓶","滴瓶"],"observation":"溶液无色。","conclusion":"硫氰化钾用于检验铁离子，生成血红色配合物。","cautions":["硫氰化钾有毒，避免误食。","废液应集中处理。"]},
"lithium-chloride":{"apparatus":["烧杯","蒸发皿","水浴锅","干燥器","pH 试纸"],"observation":"碳酸锂逐渐溶解并放出无色气泡，蒸发后得到白色立方晶体。","conclusion":"强酸制弱酸原理可用于制备可溶性锂盐；LiCl 吸水性强，必须充分干燥。","cautions":["盐酸具有腐蚀性，操作时戴护目镜与手套。","蒸发后期避免蒸干，防止晶体飞溅。"]},
"lithium-carbonate":{"apparatus":["烧杯","漏斗","抽滤瓶","烘箱"],"observation":"混合后立即出现白色沉淀，洗涤后沉淀更疏松。","conclusion":"利用溶解度差异，以可溶性锂盐与碳酸钠反应制取碳酸锂。","cautions":["碳酸钠溶液呈碱性，避免溅入眼睛。","洗涤不充分会残留氯化钠。"]},
"barium-chloride":{"apparatus":["烧杯","蒸发皿","抽滤装置","水浴锅"],"observation":"碳酸钡溶解并放出气泡，浓缩后析出白色针状晶体。","conclusion":"可溶性钡盐由碳酸钡酸解制得，重结晶可除去氯化物以外的杂质。","cautions":["可溶性钡盐有毒，严禁入口，操作后彻底洗手。","含钡废液须单独收集，按危废处理。"]},
"barium-nitrate":{"apparatus":["烧杯","蒸发皿","抽滤装置"],"observation":"白色固体溶解并放出气泡，浓缩后得到白色晶体。","conclusion":"硝酸钡可由碳酸钡直接酸解制备，属于典型的强酸制弱酸盐反应。","cautions":["硝酸具有强腐蚀性与氧化性，避免与有机物接触。","硝酸钡有毒且属氧化剂，远离可燃物保存。"]},
"calcium-nitrate":{"apparatus":["烧杯","蒸发皿","抽滤装置","水浴锅"],"observation":"石灰石表面持续冒出气泡，滤液浓缩后析出无色针状晶体。","conclusion":"硝酸钙可由碳酸钙酸解制备；控制浓缩程度可获得四水合物。","cautions":["硝酸有腐蚀性，避免吸入酸雾。","硝酸钙是强氧化剂，不可与还原性物质混放。"]},
"calcium-phosphate":{"apparatus":["烧杯","漏斗","抽滤瓶","烘箱"],"observation":"混合瞬间出现白色胶状沉淀，陈化后沉淀变得致密易过滤。","conclusion":"两种可溶性盐复分解生成难溶磷酸钙，陈化有利于晶体长大。","cautions":["磷酸钠溶液呈强碱性，避免接触皮肤。","沉淀易胶溶，洗涤时应少量多次。"]},
"magnesium-nitrate":{"apparatus":["烧杯","蒸发皿","抽滤装置","干燥器"],"observation":"固体溶解并放出气泡，冷却后析出无色晶体。","conclusion":"镁盐可由碳酸盐或碱式碳酸盐酸解制备，产物易吸潮。","cautions":["硝酸具有腐蚀性。","硝酸镁受热易分解，干燥温度不宜超过 100 ℃。"]},
"zinc-chloride":{"apparatus":["锥形瓶","蒸发皿","抽滤装置","石棉网"],"observation":"锌粒表面产生大量气泡，溶液逐渐变清；浓缩后呈黏稠状。","conclusion":"活泼金属与酸反应制盐，终点加入锌粉可置换除去较不活泼金属杂质。","cautions":["反应放出氢气，远离明火。","氯化锌腐蚀性强，避免接触皮肤与眼睛。"]},
"zinc-nitrate":{"apparatus":["烧杯","蒸发皿","抽滤装置"],"observation":"白色氧化锌溶解，溶液澄清；冷却后析出无色晶体。","conclusion":"两性氧化物可溶于酸，借此制备对应硝酸盐。","cautions":["硝酸有腐蚀性。","硝酸锌属氧化剂，避免高温与可燃物接触。"]},
"copper-chloride":{"apparatus":["烧杯","蒸发皿","抽滤装置"],"observation":"氧化铜溶解后得到蓝绿色溶液，冷却析出绿色针状晶体。","conclusion":"氯化铜的结晶水与氯配位会显著改变颜色，可用于讨论配离子。","cautions":["铜盐有毒，避免入口。","含铜废液应回收处理，不得直接排放。"]},
"copper-carbonate":{"apparatus":["烧杯","漏斗","抽滤瓶","烘箱"],"observation":"混合后产生蓝绿色沉淀，陈化后颜色转为深绿色。","conclusion":"铜盐与碳酸钠反应不是简单生成碳酸铜，而是碱式碳酸铜，说明沉淀组成受水解影响。","cautions":["铜盐有毒，避免吸入粉尘。","洗涤不充分会夹带硫酸钠。"]},
"silver-bromide":{"apparatus":["烧杯","漏斗","抽滤瓶","棕色瓶"],"observation":"生成淡黄色沉淀，光照后逐渐变灰。","conclusion":"卤化银溶解度依次减小：AgCl > AgBr > AgI，颜色依次加深。","cautions":["硝酸银腐蚀皮肤并留下黑斑，操作戴手套。","含银废液须回收，避免污染环境。"]},
"silver-iodide":{"apparatus":["烧杯","漏斗","抽滤瓶","棕色瓶"],"observation":"生成亮黄色沉淀；加氨水不溶，加硫代硫酸钠溶液溶解。","conclusion":"AgI 的溶度积很小，不能靠氨水配位溶解，但可溶于硫代硫酸钠形成配离子。","cautions":["硝酸银与碘化钾均需避免接触皮肤和眼睛。","含银废液回收处理。"]},
"lead-iodide":{"apparatus":["烧杯","漏斗","抽滤瓶","水浴锅"],"observation":"冷却过程中先出现云状浑浊，随后析出有金属光泽的金色薄片。","conclusion":"碘化铅的溶解度随温度升高明显增大，是重结晶与溶解度曲线的良好示例。","cautions":["铅盐有毒且可在体内蓄积，严禁接触食物与入口。","含铅废液必须作为危险废物回收，不得倒入下水道。"]},
"lead-nitrate":{"apparatus":["烧杯","蒸发皿","抽滤装置"],"observation":"黄色氧化铅溶解，得到无色溶液，浓缩后析出白色晶体。","conclusion":"硝酸铅可由铅的氧化物酸解制备，属于可溶性铅盐。","cautions":["铅盐剧毒，操作必须戴手套并在通风处进行。","含铅废物与废液按危险废物处理。"]},
"iron-phosphate":{"apparatus":["烧杯","漏斗","抽滤瓶","烘箱"],"observation":"生成浅黄色沉淀，陈化后颜色略深。","conclusion":"控制酸度可抑制 Fe³⁺ 水解，使磷酸铁沉淀更纯净。","cautions":["氯化铁溶液腐蚀性强，会染黄皮肤。","磷酸钠溶液呈碱性，避免溅入眼睛。"]},
"aluminium-iodide":{"apparatus":["干燥的圆底烧瓶","回流冷凝管","干燥管","通风橱"],"observation":"加热后出现紫色碘蒸气，反应剧烈放热，瓶内产生白色烟雾。","conclusion":"无水条件下铝与碘可直接化合；产物极易水解，说明卤化铝的共价性与水解性。","cautions":["反应放热剧烈，必须在通风橱内小量进行。","碘蒸气刺激呼吸道，产物遇水放出腐蚀性 HI，严禁接触水汽。"]},
"sodium-iodide":{"apparatus":["烧杯","蒸发皿","抽滤装置","棕色瓶"],"observation":"加入酸后放出无色气泡，浓缩析出白色晶体，久置表面泛黄。","conclusion":"碘化钠易氧化析出碘，故需避光、密封保存。","cautions":["氢碘酸有强腐蚀性，且在空气中发烟。","碘化钠见光易变质，不宜长期敞口放置。"]},
"ammonium-nitrate":{"apparatus":["烧杯","蒸发皿","pH 计","抽滤装置"],"observation":"中和时放热，浓缩后析出白色晶体；溶解时温度明显下降。","conclusion":"弱碱与强酸中和生成可溶性铵盐，溶解热的符号可通过温度变化判断。","cautions":["硝酸铵是氧化剂，受热或受冲击可能分解，禁止大量堆积与密闭加热。","不得与可燃物、还原剂混合存放。"]},
"ammonium-bicarbonate":{"apparatus":["锥形瓶","导管","冰水浴","抽滤装置"],"observation":"通入二氧化碳后溶液逐渐浑浊，最终析出白色针状晶体。","conclusion":"碳酸氢铵溶解度较小，在氨盐水中优先析出，是候氏制碱法的关键一步。","cautions":["氨水刺激性很强，操作在通风橱内进行。","产品受热易分解，须低温密封保存。"]},
"ammonium-phosphate":{"apparatus":["烧杯","蒸发皿","pH 计","抽滤装置"],"observation":"中和时放热并产生白雾，浓缩后析出白色晶体。","conclusion":"多元酸与氨中和可生成正盐，pH 控制决定产物组成。","cautions":["氨水与磷酸均有腐蚀性，操作戴护目镜。","铵盐遇强碱会放出氨气，避免混存。"]},
"potassium-sulfate":{"apparatus":["烧杯","蒸发皿","抽滤装置"],"observation":"加入硫酸后放出气泡，浓缩析出无色晶体。","conclusion":"碳酸盐与酸反应生成可溶性硫酸盐，重结晶可提高纯度。","cautions":["稀硫酸有腐蚀性，避免溅到皮肤。","蒸发时防止局部过热导致飞溅。"]},
"potassium-dichromate":{"apparatus":["烧杯","蒸发皿","抽滤装置","棕色瓶"],"observation":"溶液呈橙色，冷却后析出橙红色晶体。","conclusion":"利用溶解度差异进行复分解与重结晶，是制备重铬酸钾的常用方法。","cautions":["重铬酸钾含六价铬，强致癌、强氧化，必须戴手套在通风橱内操作。","含铬废液须还原为三价铬后按危废处理，严禁排放。"]},
"sodium-tetraborate":{"apparatus":["烧杯","蒸发皿","抽滤装置","pH 计"],"observation":"硼酸溶解后加入碱，溶液保持澄清；冷却析出白色晶体。","conclusion":"硼砂是硼酸的正盐，其水溶液因硼酸根水解而呈碱性。","cautions":["硼砂有生殖毒性，避免入口与长期接触。","氢氧化钠溶液腐蚀性强，操作戴手套。"]},
"iron-ammonium-sulfate":{"apparatus":["烧杯","蒸发皿","抽滤装置","棕色瓶"],"observation":"浓缩后析出浅紫色八面体晶体，溶于水呈淡黄色。","conclusion":"复盐的结晶要求两种盐按化学计量比结合，酸度可抑制 Fe³⁺ 水解。","cautions":["硫酸铁溶液腐蚀性强，会污染衣物。","避免与强还原剂混放。"]},
"manganese-sulfate":{"apparatus":["烧杯","水浴锅","抽滤装置","蒸发皿"],"observation":"黑色固体逐渐溶解，溶液呈淡粉色，同时放出氧气。","conclusion":"过氧化氢在酸性条件下可还原二氧化锰，是软锰矿湿法处理的典型反应。","cautions":["过氧化氢具腐蚀性与氧化性，避免接触皮肤。","锰盐有一定毒性，避免吸入粉尘。"]},
"barium-oxide":{"apparatus":["坩埚","马弗炉","干燥器","防护面罩"],"observation":"煅烧后白色粉末变得致密，加水后剧烈放热并生成强碱性溶液。","conclusion":"难溶性碳酸盐高温分解生成碱性氧化物，是制备金属氧化物的通用方法。","cautions":["氧化钡遇水剧烈放热，可能造成烫伤与碱性灼伤。","必须在通风橱与高温防护下操作，产物密封防潮。"]},
"strontium-oxide":{"apparatus":["坩埚","马弗炉","干燥器"],"observation":"产物为白色多孔固体，加水后放热并生成氢氧化锶。","conclusion":"碱土金属碳酸盐的热稳定性随金属活动性增强而提高，需更高温度分解。","cautions":["高温操作须戴隔热手套与面罩。","氧化锶遇水放热，避免直接接触皮肤。"]},
"zinc-oxide":{"apparatus":["坩埚","马弗炉","试管"],"observation":"白色粉末遇盐酸与氢氧化钠溶液均溶解，说明其两性。","conclusion":"氧化锌既能与酸反应又能与碱反应，是典型的两性氧化物。","cautions":["氧化锌粉尘刺激呼吸道，操作时佩戴口罩。","氢氧化钠溶液有腐蚀性。"]},
"lead-monoxide":{"apparatus":["坩埚","马弗炉","通风橱","干燥器"],"observation":"加热时放出红棕色二氧化氮，残留物由白色变为黄色。","conclusion":"硝酸盐热分解生成金属氧化物、二氧化氮与氧气，是制备金属氧化物的一种途径。","cautions":["铅化合物剧毒，全程戴手套、口罩并在通风橱内操作。","二氧化氮有毒，尾气需用碱液吸收。"]},
"magnetite":{"apparatus":["烧杯","磁铁","抽滤瓶","烘箱"],"observation":"生成黑色沉淀，磁铁可使沉淀向杯壁聚集。","conclusion":"共沉淀法可制备组成均匀的混合价氧化物，磁性可作为产物判断依据。","cautions":["氢氧化钠溶液腐蚀性强。","亚铁盐易被空气氧化，操作应迅速。"]},
"chromium-oxide":{"apparatus":["坩埚","酒精灯","通风橱","石棉网"],"observation":"加热后橙红色固体迅速膨胀，放出气体并变为绿色蓬松固体。","conclusion":"重铬酸铵分解是分子内氧化还原反应，Cr(VI) 被还原为 Cr(III)。","cautions":["重铬酸铵含六价铬且受热分解剧烈，只可极少量演示。","反应放出含铬粉尘与氮气，必须在通风橱内进行，残渣按危废处理。"]},
"titanium-dioxide":{"apparatus":["烧杯","抽滤瓶","坩埚","马弗炉","通风橱"],"observation":"四氯化钛遇水剧烈水解，产生白雾与白色胶状沉淀。","conclusion":"四氯化钛水解是制备高纯二氧化钛的经典方法，酸度控制决定颗粒形貌。","cautions":["四氯化钛遇水剧烈水解并放出氯化氢，必须在通风橱内缓慢操作。","煅烧温度高，注意防烫。"]},
"tin-dioxide":{"apparatus":["烧杯","抽滤瓶","坩埚","马弗炉","通风橱"],"observation":"锡表面生成白色蓬松沉淀，同时放出红棕色二氧化氮。","conclusion":"浓硝酸将锡氧化为 Sn(IV)，得到水合氧化物，煅烧后脱水。","cautions":["浓硝酸与二氧化氮均有强腐蚀性和毒性，必须在通风橱内操作。","反应放热剧烈，锡用量要少。"]},
"copper-i-oxide":{"apparatus":["试管","水浴锅","离心机"],"observation":"溶液由蓝色变为绿色，随后出现黄色浑浊，最终生成砖红色沉淀。","conclusion":"醛基在碱性条件下还原 Cu(II) 为 Cu(I)，颜色变化可用于检验还原糖。","cautions":["氢氧化钠有腐蚀性，水浴加热时避免试管口对人。","含铜废液回收处理。"]},
"nickel-oxide":{"apparatus":["坩埚","马弗炉","通风橱"],"observation":"煅烧后得到灰绿色固体，溶于盐酸后呈绿色。","conclusion":"镍盐热分解可制备氧化镍，产物颜色与镍的氧化态有关。","cautions":["镍化合物可能致敏，避免粉尘接触皮肤。","高温操作注意防烫。"]},
"lithium-hydroxide":{"apparatus":["烧杯","漏斗","蒸发皿","抽滤装置"],"observation":"煮沸后悬浊液变稠，过滤得到澄清滤液，浓缩析出白色晶体。","conclusion":"利用 CaCO₃ 难溶推动反应进行，是制备氢氧化锂的苛化法。","cautions":["氢氧化锂是强碱，腐蚀性强。","产物易吸收二氧化碳，必须密封保存。"]},
"strontium-hydroxide":{"apparatus":["烧杯","抽滤装置","干燥器"],"observation":"氧化锶水合时放热，冷却后析出无色透明晶体。","conclusion":"碱土金属氢氧化物溶解度随金属离子半径增大而增大，氢氧化锶比氢氧化钙易溶。","cautions":["氢氧化锶是强碱，避免接触皮肤与眼睛。","晶体加热会失水，干燥温度不宜过高。"]},
"hydriodic-acid":{"apparatus":["蒸馏烧瓶","冷凝管","接收瓶","冰水浴"],"observation":"馏出液为无色透明液体，在空气中逐渐变黄。","conclusion":"难挥发性酸可制取挥发性酸；HI 还原性强，容易被空气氧化。","cautions":["氢碘酸有强腐蚀性，蒸气刺激呼吸道，全程通风橱操作。","避免与氧化剂接触，废液交实验员统一处理，不要自行中和。"]},
"hydrobromic-acid":{"apparatus":["蒸馏烧瓶","冷凝管","接收瓶","通风橱"],"observation":"馏出液无色，遇硝酸银生成淡黄色溴化银沉淀。","conclusion":"用难挥发性磷酸制取 HBr，避免硫酸氧化溴离子。","cautions":["氢溴酸与溴化氢气体均有强腐蚀性，必须在通风橱内操作。","溴化物废液不可与氧化剂混合。"]},
"nitrous-acid":{"apparatus":["烧杯","冰水浴","温度计","通风橱"],"observation":"溶液呈淡蓝色，放置后放出红棕色气体并逐渐分解。","conclusion":"亚硝酸不稳定，只能在低温下临时配制，具有氧化性和还原性。","cautions":["亚硝酸及其分解产物有毒，必须在通风橱内小量操作。","亚硝酸盐有致癌风险，严禁入口与长期接触。"]},
"nitric-oxide":{"apparatus":["圆底烧瓶","分液漏斗","排水集气装置","通风橱"],"observation":"瓶内先得到无色气体，打开后立即变为红棕色。","conclusion":"稀硝酸还原产物以 NO 为主，NO 易被氧化为 NO₂。","cautions":["氮氧化物有毒，全部操作在通风橱内进行，尾气用碱液吸收。","反应放热，注意控制加酸速度。"]},
"nitrogen-dioxide":{"apparatus":["圆底烧瓶","导管","集气瓶","通风橱"],"observation":"气体呈红棕色；冰水浴中颜色变浅，热水中颜色加深。","conclusion":"NO₂ 与 N₂O₄ 之间存在温度依赖的二聚平衡，颜色变化可指示平衡移动。","cautions":["二氧化氮剧毒，严禁泄漏，必须在通风橱内操作。","浓硝酸腐蚀性强，尾气必须吸收。"]},
"nitrous-oxide":{"apparatus":["圆底烧瓶","油浴","温度计","排水集气装置"],"observation":"收集到无色气体，闻起来略有甜味（不可主动嗅闻）。","conclusion":"硝酸铵在特定温度下发生分子内氧化还原，生成 N₂O。","cautions":["硝酸铵受热可能爆炸，严禁密闭加热与超温。","N₂O 为温室气体并可致欣快，严禁吸食。"]},
"sulfur-dioxide":{"apparatus":["圆底烧瓶","分液漏斗","向上排空气集气瓶","通风橱"],"observation":"生成有刺激性气味的气体，使品红溶液褪色，加热后红色恢复。","conclusion":"SO₂ 具有漂白性，其漂白是可逆的，与氯水的不可逆漂白不同。","cautions":["二氧化硫刺激呼吸道，所有操作在通风橱内进行。","尾气必须用碱液吸收，避免污染室内空气。"]},
"hydrogen-sulfide":{"apparatus":["启普发生器或锥形瓶","导管","通风橱"],"observation":"产生臭鸡蛋气味气体，通入硫酸铜生成黑色沉淀，高锰酸钾褪色。","conclusion":"H₂S 是弱酸且还原性强，可与多种金属离子生成难溶硫化物。","cautions":["硫化氢剧毒，浓度高时可致嗅觉麻痹，必须在通风橱内操作。","尾气必须吸收，严禁直接排放。"]},
"carbon-monoxide":{"apparatus":["圆底烧瓶","分液漏斗","硬质玻璃管","尾气处理装置"],"observation":"氧化铜由黑色变为红色，澄清石灰水变浑浊。","conclusion":"CO 具有还原性，可将金属氧化物还原为金属，自身被氧化为 CO₂。","cautions":["一氧化碳无色无味、剧毒，必须在通风橱内并配备尾气处理。","严禁在密闭空间内进行，实验结束先通入氮气再拆卸装置。"]},
"hydrogen-chloride-gas":{"apparatus":["圆底烧瓶","分液漏斗","干燥管","集气瓶"],"observation":"产生无色刺激性气体，遇水蒸气形成白雾。","conclusion":"高沸点酸可制取低沸点酸；氯化氢极易溶于水，可形成喷泉。","cautions":["氯化氢气体腐蚀性强，必须在通风橱内操作。","尾气必须吸收，防止倒吸。"]},
"sodium-hypochlorite":{"apparatus":["广口瓶","导管","冰水浴","通风橱"],"observation":"溶液呈淡黄绿色，能使品红溶液褪色。","conclusion":"氯气在碱中发生歧化，生成次氯酸盐，具有漂白与消毒作用。","cautions":["氯气有毒，操作必须在通风橱内进行。","次氯酸钠与酸混合会放出氯气，严禁与洁厕灵等酸性清洁剂混用。"]},
"calcium-carbide":{"apparatus":["石墨坩埚","电弧炉","干燥器"],"observation":"产物遇水剧烈反应，放出有特殊气味的气体，并生成白色糊状物。","conclusion":"高温下碳还原氧化钙生成碳化物，碳化钙水解是实验室制乙炔的方法。","cautions":["电弧炉操作危险，仅限工业或专业实验室。","碳化钙遇水放出易燃乙炔，严禁受潮与密闭存放。"]},
"formaldehyde":{"apparatus":["硬质玻璃管","酒精灯","洗气瓶","通风橱"],"observation":"红热铜丝保持红热，吸收液能使斐林试剂生成砖红色沉淀。","conclusion":"伯醇在催化剂表面脱氢并被氧化，生成醛；铜是良好的脱氢催化剂。","cautions":["甲醛有毒且致癌，必须在通风橱内操作。","甲醇有毒，禁止入口，废液回收。"]},
"formic-acid":{"apparatus":["蒸馏烧瓶","冷凝管","减压装置","冰水浴"],"observation":"得到无色有刺激性气味的液体，能使紫色石蕊变红。","conclusion":"甲酸是最简单的羧酸，兼具羧基与醛基，受热易脱水生成一氧化碳。","cautions":["甲酸腐蚀皮肤，浓硫酸遇水放热，必须缓慢加酸。","蒸馏温度过高会分解产生一氧化碳，需减压。"]},
"oxalic-acid":{"apparatus":["坩埚","马弗炉","烧杯","结晶皿"],"observation":"加热时有气体放出，酸化后析出无色柱状晶体。","conclusion":"甲酸盐高温脱氢偶联生成草酸盐，酸化后得到草酸。","cautions":["草酸有毒，可造成肾损伤，避免入口与粉尘吸入。","酸化时放热，缓慢加入并冷却。"]},
"tartaric-acid":{"apparatus":["烧杯","抽滤装置","蒸发皿","结晶皿"],"observation":"加入石灰乳生成白色沉淀，酸化后沉淀转为硫酸钙，滤液浓缩析出晶体。","conclusion":"利用钙盐溶解度差异实现酒石酸的分离与提纯。","cautions":["硫酸有腐蚀性，操作时戴手套。","浓缩时避免局部过热导致碳化。"]},
"salicylic-acid":{"apparatus":["高压反应釜","油浴","抽滤装置","通风橱"],"observation":"酸化后析出白色针状晶体，遇三氯化铁溶液显紫色。","conclusion":"酚钠的邻位羧基化是制备水杨酸的工业方法，羟基使苯环活化。","cautions":["高压操作有风险，仅限专业设备。","苯酚腐蚀皮肤，硫酸有强腐蚀性。"]},
"methyl-salicylate":{"apparatus":["圆底烧瓶","回流冷凝管","分液漏斗","蒸馏装置"],"observation":"反应液有冬青油香味，洗涤后得到无色油状液体。","conclusion":"羧酸与醇在酸催化下生成酯，水杨酸的酚羟基不参与酯化。","cautions":["甲醇有毒，严禁入口与吸入蒸气。","浓硫酸腐蚀性强，加料时缓慢混合。"]},
"methyl-benzoate":{"apparatus":["圆底烧瓶","回流冷凝管","分液漏斗","蒸馏装置"],"observation":"馏出液有类似水果的香味，为无色透明液体。","conclusion":"苯甲酸与甲醇发生酯化，产物沸点与原料差异可用于蒸馏提纯。","cautions":["甲醇有毒，蒸馏时注意冷凝充分。","浓硫酸有腐蚀性。"]},
"ethyl-formate":{"apparatus":["圆底烧瓶","回流冷凝管","分馏柱","接收瓶"],"observation":"收集到低沸点无色液体，有果香与朗姆酒气味。","conclusion":"低沸点酯可通过分馏从反应混合物中移出，推动酯化平衡右移。","cautions":["甲酸与甲酸乙酯易燃，远离明火。","浓硫酸有腐蚀性，加料时冷却。"]},
"isoamyl-acetate":{"apparatus":["圆底烧瓶","回流冷凝管","分液漏斗","蒸馏装置"],"observation":"产物有浓郁香蕉香味，为无色油状液体。","conclusion":"酯化反应中醇与酸的种类决定酯的香味，可用于香料制备。","cautions":["乙酸有刺激性，浓硫酸腐蚀性强。","蒸馏时避免暴沸，加入沸石。"]},
"iodoform":{"apparatus":["试管","水浴锅","抽滤装置"],"observation":"生成黄色有特殊气味的沉淀，显微镜下呈六角形片状。","conclusion":"含 CH₃CO— 或 CH₃CH(OH)— 结构的化合物可发生卤仿反应。","cautions":["碘蒸气刺激呼吸道，操作在通风橱内进行。","碘仿遇光分解，产物避光保存。"]},
"dibromoethane":{"apparatus":["蒸馏烧瓶","温度计","洗气瓶","冰水浴"],"observation":"溴的红棕色褪去，得到无色密度较大的液体。","conclusion":"乙烯与溴发生加成反应，碳碳双键转化为单键。","cautions":["溴剧毒且腐蚀性强，乙烯制备可能发生倒吸，必须在通风橱内操作。","浓硫酸与乙醇混合放热，需冷却后加料。"]},
"ethylene-glycol":{"apparatus":["圆底烧瓶","回流冷凝管","蒸馏装置"],"observation":"回流后油层逐渐消失，得到黏稠无色液体。","conclusion":"邻二卤代烃在碱性条件下水解生成邻二醇。","cautions":["乙二醇有毒，严禁入口。","二溴乙烷有刺激性，操作在通风橱内进行。"]},
"benzyl-alcohol":{"apparatus":["圆底烧瓶","回流冷凝管","分液漏斗","蒸馏装置"],"observation":"回流时油状氯化苄逐渐减少，产物有微弱花香。","conclusion":"苄基氯水解生成苯甲醇，苄基碳正离子稳定使反应容易进行。","cautions":["氯化苄催泪且刺激皮肤，必须在通风橱内操作。","乙醚易燃，蒸馏时严禁明火。"]},
"benzaldehyde":{"apparatus":["圆底烧瓶","回流冷凝管","抽滤装置","蒸馏装置"],"observation":"产物有苦杏仁气味，TLC 显示原料点消失。","conclusion":"活性二氧化锰可选择性氧化苄醇为醛，不进一步氧化为酸。","cautions":["苯甲醛有刺激性，避免吸入蒸气。","乙醚易燃，操作远离火源。"]},
"benzyl-chloride":{"apparatus":["三口烧瓶","紫外灯","尾气吸收装置","通风橱"],"observation":"反应液逐渐变稠，尾气使湿润蓝色石蕊试纸变红。","conclusion":"光照下甲苯侧链发生自由基取代，苯环在无催化剂时不被取代。","cautions":["氯气剧毒，氯化苄催泪，全程通风橱与尾气吸收。","严禁明火，氯气与有机物混合物有爆炸风险。"]},
"cinnamic-acid":{"apparatus":["圆底烧瓶","回流冷凝管","水蒸气蒸馏装置","抽滤装置"],"observation":"酸化后析出白色片状晶体，熔点约 133 ℃。","conclusion":"芳香醛与酸酐在碱催化下缩合，是制备 α,β-不饱和酸的经典方法。","cautions":["乙酸酐腐蚀性强，苯甲醛有刺激性。","水蒸气蒸馏时注意防烫与防倒吸。"]},
"coumarin":{"apparatus":["圆底烧瓶","油浴","抽滤装置","通风橱"],"observation":"反应液变为深色，倒入冰水后析出浅黄色固体，有香草气味。","conclusion":"酚与 β-酮酸在酸催化下缩合环化，生成香豆素骨架。","cautions":["浓硫酸腐蚀性强，苯酚有毒，必须在通风橱内操作。","反应可能剧烈放热，加酸要缓慢。"]},
"phenolphthalein":{"apparatus":["圆底烧瓶","油浴","抽滤装置","通风橱"],"observation":"粗品为白色至淡黄色固体，溶于乙醇后滴入碱液显粉红色。","conclusion":"酸酐与酚发生傅-克酰基化并闭环，生成三苯甲烷类指示剂。","cautions":["苯酚有毒且腐蚀皮肤，浓硫酸有强腐蚀性。","反应温度不宜过高，避免碳化。"]},
"fluorescein":{"apparatus":["圆底烧瓶","油浴","抽滤装置"],"observation":"产物为橙红色粉末，碱溶液在光照下发出黄绿色荧光。","conclusion":"荧光素是呫吨类染料，共轭体系使其在可见光区强吸收并发射荧光。","cautions":["间苯二酚有毒，避免接触皮肤。","高温操作注意防烫，废液按染料废液处理。"]},
"bakelite":{"apparatus":["烧杯","水浴锅","模具","烘箱","通风橱"],"observation":"树脂由黏稠液体逐渐固化为棕色硬质固体。","conclusion":"酚醛缩聚分阶段进行，固化后形成交联网络，具有热固性。","cautions":["苯酚与甲醛均有毒且致癌，必须在通风橱内操作。","固化过程放热，模具不宜过大。"]},
"urea-formaldehyde-resin":{"apparatus":["烧杯","水浴锅","搅拌棒","通风橱"],"observation":"反应液逐渐变稠，固化后为无色至浅黄色硬质固体。","conclusion":"尿素与甲醛的缩聚产物是氨基树脂，交联程度决定硬度。","cautions":["甲醛有毒且致癌，必须在通风橱内操作。","固化时可能释放甲醛，注意通风。"]},
"polystyrene":{"apparatus":["试管","水浴锅","烘箱","通风橱"],"observation":"反应液由流动液体变为黏稠糖浆状，倒入甲醇后析出白色絮状固体。","conclusion":"苯乙烯的自由基聚合可通过引发剂与温度控制，产物为非晶态热塑性塑料。","cautions":["苯乙烯易燃且有刺激性，聚合放热可能暴聚。","过氧化苯甲酰受热易分解，避免大量使用。"]},
"nylon-66":{"apparatus":["烧杯","镊子","玻璃棒","通风橱"],"observation":"两相界面迅速生成白色薄膜，可连续拉出坚韧的丝。","conclusion":"界面缩聚反应速率快，可在常温下制备聚酰胺。","cautions":["己二酰氯与己二胺均有腐蚀性，必须在通风橱内操作。","环己烷易燃，远离火源。"]},
"casein":{"apparatus":["烧杯","水浴锅","纱布","抽滤装置"],"observation":"牛奶出现白色凝块，滤液变为半透明的乳清。","conclusion":"蛋白质在等电点时净电荷为零，溶解度最低而沉淀。","cautions":["乙酸有刺激性，避免溅入眼睛。","乳制品过敏者避免接触。"]},
"starch":{"apparatus":["研钵","纱布","烧杯","烘箱"],"observation":"底部沉积白色细腻粉末，遇碘液变蓝。","conclusion":"淀粉是植物储能多糖，可通过物理分离从块茎中提取。","cautions":["使用锋利工具时注意安全。","干燥温度不宜过高，避免糊化。"]},
"sucrose":{"apparatus":["榨汁机","烧杯","抽滤装置","结晶皿"],"observation":"糖浆冷却后析出白色晶体，母液为黄褐色糖蜜。","conclusion":"蔗糖的提纯包括澄清、脱色、浓缩与结晶，是天然产物加工的典型流程。","cautions":["石灰乳有腐蚀性，避免接触皮肤。","浓缩糖浆温度高，注意防烫。"]},
"butanone":{"apparatus":["圆底烧瓶","回流冷凝管","蒸馏装置","冰水浴"],"observation":"氧化液由橙色变为绿色，馏出液有丙酮样气味。","conclusion":"仲醇被酸性重铬酸钾氧化为酮，铬(VI) 被还原为铬(III)。","cautions":["重铬酸钾含六价铬，致癌且污染环境，必须回收废液。","丁酮易燃，蒸馏时严禁明火。"]},
"acetamide":{"apparatus":["烧杯","冰水浴","抽滤装置","通风橱"],"observation":"反应放热并产生白烟，冷却后析出白色片状晶体。","conclusion":"酸酐与氨发生酰化反应生成酰胺，是制备酰胺的常用方法。","cautions":["乙酸酐腐蚀性强，氨水刺激性大，必须在通风橱内操作。","反应放热剧烈，必须缓慢加料并冷却。"]},
"chloroacetic-acid":{"apparatus":["三口烧瓶","回流冷凝管","尾气吸收装置","通风橱"],"observation":"反应液颜色加深，冷却后析出白色晶体。","conclusion":"羧基的吸电子作用使 α-氢活泼，可被卤素取代。","cautions":["氯乙酸剧毒且腐蚀性强，可致严重灼伤，必须全防护操作。","氯气有毒，尾气必须吸收。"]},
"sodium-acetate":{"apparatus":["烧杯","蒸发皿","烘箱","pH 试纸"],"observation":"中和时放出二氧化碳，浓缩后析出无色晶体。","conclusion":"弱酸与碳酸盐反应生成盐，加热可脱去结晶水。","cautions":["乙酸有刺激性，操作时注意通风。","蒸发浓缩时防止暴沸。"]},
"phenolphthalein-solution":{"apparatus":["容量瓶","滴管","试剂瓶"],"observation":"溶液无色，滴入碱液后变为粉红色。","conclusion":"指示剂浓度影响变色敏锐度，1% 乙醇溶液是常用配比。","cautions":["乙醇易燃，远离明火。","酚酞溶液应避光保存，避免误食。"]},
"universal-indicator":{"apparatus":["烧杯","容量瓶","滴瓶"],"observation":"酸性呈红橙，中性呈黄绿，碱性呈蓝紫。","conclusion":"混合指示剂可扩大变色范围，适合课堂教学的粗略 pH 判断。","cautions":["含乙醇，易燃。","强酸强碱测试时注意防护。"]},
"benedict-reagent":{"apparatus":["烧杯","容量瓶","水浴锅"],"observation":"试剂为深蓝色，与葡萄糖共热后生成砖红色沉淀。","conclusion":"络合剂使 Cu²⁺ 在碱性中稳定，还原糖可将其还原。","cautions":["氢氧化钠与碳酸钠有腐蚀性。","含铜废液应回收，不可直接排放。"]},
"schiff-reagent":{"apparatus":["烧杯","容量瓶","棕色瓶","通风橱"],"observation":"溶液由紫红色变为无色，加入乙醛后重新显紫红色。","conclusion":"希夫试剂可用于醛基检验，反应灵敏但需现配避光保存。","cautions":["品红与亚硫酸盐有刺激性，操作在通风橱内。","试剂易变质，出现粉红色即失效。"]},
"potassium-chromate-indicator":{"apparatus":["容量瓶","滴瓶","分析天平"],"observation":"终点时出现砖红色浑浊。","conclusion":"沉淀滴定中指示剂与滴定剂生成有色沉淀，指示终点。","cautions":["铬酸钾含六价铬，致癌且污染环境，必须戴手套并回收废液。","避免粉尘吸入。"]},
"edta-standard":{"apparatus":["分析天平","容量瓶","干燥器","pH 计"],"observation":"溶液无色透明，滴定终点由紫红变纯蓝。","conclusion":"EDTA 标准溶液是络合滴定测定水硬度与金属离子的基础试剂。","cautions":["络合滴定需控制 pH，操作按标准方法进行。","废液含金属络合物，集中处理。"]},
"thiosulfate-standard":{"apparatus":["分析天平","容量瓶","棕色瓶","滴定管"],"observation":"滴定至浅黄后加淀粉，继续滴至蓝色消失为终点。","conclusion":"间接碘量法用硫代硫酸钠滴定生成的碘，可测定氧化性物质。","cautions":["重铬酸钾含六价铬，注意防护与废液处理。","溶液应避光保存，防止浓度变化。"]},
"permanganate-standard":{"apparatus":["分析天平","棕色瓶","滴定管","水浴锅"],"observation":"标定时溶液由紫红变为无色，终点为微红色。","conclusion":"高锰酸钾法在酸性条件下氧化性强，可用于测定还原性物质。","cautions":["高锰酸钾腐蚀性强，避免接触皮肤与衣物。","溶液见光分解，必须避光保存。"]},
"silver-nitrate-standard":{"apparatus":["分析天平","容量瓶","棕色瓶","滴定管"],"observation":"滴定终点出现砖红色铬酸银沉淀。","conclusion":"硝酸银标准溶液是沉淀滴定测定卤离子的核心试剂。","cautions":["硝酸银腐蚀皮肤并使衣物变黑，避免接触。","避光保存，废液银回收。"]},
"hcl-standard":{"apparatus":["量筒","容量瓶","滴定管","分析天平"],"observation":"滴定终点溶液由绿色变为暗红色，煮沸后颜色不恢复。","conclusion":"基准碳酸钠标定盐酸，适用于酸碱滴定。","cautions":["浓盐酸挥发刺激，稀释时酸入水。","滴定管使用前需润洗。"]},
"naoh-standard":{"apparatus":["塑料瓶","滴定管","分析天平","容量瓶"],"observation":"终点溶液呈浅粉红色，30 s 不褪色。","conclusion":"氢氧化钠标准溶液需排除碳酸钠干扰，并现用现标。","cautions":["氢氧化钠腐蚀性强，戴手套与护目镜。","溶液应密封保存，防止吸收二氧化碳。"]},
"buffer-ph4":{"apparatus":["分析天平","容量瓶","pH 计","干燥器"],"observation":"溶液 pH 计读数为 4.00 ± 0.02。","conclusion":"基准缓冲液用于校准 pH 计，配制需使用新鲜蒸馏水。","cautions":["缓冲液易长菌，加入少量防腐剂或冷藏。","校准前注意温度补偿。"]},
"buffer-ph7":{"apparatus":["分析天平","容量瓶","pH 计","干燥器"],"observation":"溶液无色，pH 计显示 6.86 左右。","conclusion":"共轭酸碱对构成缓冲体系，pH 由 pKa 与浓度比决定。","cautions":["缓冲液应新鲜配制，避免微生物污染。","含磷酸盐废液按实验室要求回收，不要直接排放。"]},
"buffer-ph10":{"apparatus":["分析天平","容量瓶","pH 计"],"observation":"溶液 pH 约为 10，能使酚酞显红色。","conclusion":"碳酸盐缓冲体系适用于需要弱碱性条件的络合滴定。","cautions":["溶液吸收二氧化碳后 pH 下降，应密封保存。","避免与酸混合产生二氧化碳。"]},
"iodine-standard":{"apparatus":["分析天平","棕色瓶","滴定管","研钵"],"observation":"溶液为深棕色，滴定至浅黄后加淀粉，终点蓝色消失。","conclusion":"碘量法利用碘的氧化性与碘离子的还原性，需避光防止碘挥发。","cautions":["碘蒸气刺激呼吸道且污染衣物，操作在通风橱内。","溶液避光密封，防止浓度下降。"]},
"barium-chloride-solution":{"apparatus":["容量瓶","滴瓶","分析天平"],"observation":"生成白色沉淀，加稀盐酸不溶解。","conclusion":"钡离子与硫酸根生成难溶硫酸钡，是检验硫酸根的经典反应。","cautions":["可溶性钡盐剧毒，严禁入口，操作戴手套。","废液加硫酸钠沉淀后处理。"]},
"silica-gel":{"apparatus":["烧杯","透析袋","烘箱","研钵"],"observation":"酸化后立即形成透明凝胶，干燥后变为白色硬块。","conclusion":"硅酸凝胶脱水形成多孔二氧化硅，比表面积大，可作干燥剂与吸附剂。","cautions":["盐酸有腐蚀性。","硅胶粉尘刺激呼吸道，研磨时佩戴口罩。"]},
"plaster-of-paris":{"apparatus":["烘箱","研钵","模具"],"observation":"加水后浆体放热并逐渐变硬，体积略有膨胀。","conclusion":"石膏的脱水与水合是可逆过程，熟石膏用于模型与医用固定。","cautions":["固化放热，避免大量堆放在皮肤上。","熟石膏吸潮后失效，需密封保存。"]},
"ferric-chloride-etchant":{"apparatus":["塑料容器","玻璃棒","天平"],"observation":"溶液由黄棕色变为黄绿色，铜箔逐渐溶解露出基材。","conclusion":"三氯化铁是常用的氧化性蚀刻剂，酸度影响蚀刻速率。","cautions":["三氯化铁腐蚀皮肤与衣物，操作戴手套。","废液含铜，必须回收处理，不可倒入下水道。"]},
"copper-plating-bath":{"apparatus":["塑料槽","铜阳极","直流电源","导线"],"observation":"阴极表面逐渐覆盖红色铜层，镀层均匀光亮。","conclusion":"电镀液提供金属离子，电流密度与添加剂影响镀层质量。","cautions":["浓硫酸腐蚀性强，必须酸入水并冷却。","电镀废液含铜，集中回收。"]},
"copper-metal":{"apparatus":["硬质玻璃管","酒精灯","电解槽","直流电源","导线"],"observation":"氧化铜由黑变红，管口有水珠；电解时阴极增重、阳极产生氧气。","conclusion":"铜可由还原法或电解法从化合物中制得，活动性较弱的金属易被还原。","cautions":["氢气与空气混合遇明火会爆炸，必须先排空气再加热。","电解使用低压直流电源，避免短路。","实验后铜粉要洗净干燥保存，防止氧化。"]},
"iron-metal":{"apparatus":["硬质玻璃管","酒精喷灯","尾气处理装置","坩埚","砂纸"],"observation":"红棕色氧化铁变黑；铝热反应放出强光高热，生成熔融铁。","conclusion":"铁可用还原剂从氧化物中还原制得，铝热法适合野外焊接。","cautions":["一氧化碳剧毒，必须在通风橱内并处理尾气。","铝热反应温度极高、飞溅危险，仅教师演示。","铁粉细而活泼，密封防潮防氧化。"]},
"zinc-metal":{"apparatus":["电解槽","直流电源","导线","蒸发皿"],"observation":"阴极析出银灰色金属，阳极有气泡产生。","conclusion":"锌可通过电解其盐溶液制得，工业上常用电解精炼。","cautions":["硫酸锌溶液不可饮用，操作后洗手。","避免电源短路与溶液过热。","锌粉易燃，干燥时远离火源。"]},
"aluminium-metal":{"apparatus":["电解炉","石墨电极","直流电源","坩埚"],"observation":"阴极生成银白色熔融铝，阳极石墨逐渐消耗并放出氧气。","conclusion":"铝的活泼性强，只能用电解熔融氧化物的方法冶炼。","cautions":["高温熔融物与强电流极其危险，仅作原理学习，禁止家庭模仿。","冰晶石含氟，需专业通风与防护。","铝粉与氧化铁混合物遇火剧烈反应。"]},
"magnesium-metal":{"apparatus":["电解炉","坩埚","直流电源","防护屏"],"observation":"阴极生成银白色轻金属，阳极产生黄绿色刺激性气体。","conclusion":"镁由电解熔融氯化镁制得，氯气需回收处理。","cautions":["氯气有毒，必须密闭收集与碱液吸收。","镁燃烧发出强光，不可直视。","仅教师演示原理，禁止自行电解。"]},
"silicon":{"apparatus":["坩埚","酒精喷灯","药匙","防护屏"],"observation":"混合物剧烈燃烧放热，得到灰黑色粉末。","conclusion":"硅可用活泼金属还原其氧化物制得，高纯硅需进一步提纯。","cautions":["反应强放热并可能喷溅，戴护目镜。","镁粉易燃，远离明火存放。","粗硅用酸洗时注意通风。"]},
"sulfur":{"apparatus":["试管","胶头滴管","漏斗","滤纸"],"observation":"溶液迅速变浑浊，析出淡黄色沉淀，同时有刺激性气体。","conclusion":"硫可由硫代硫酸盐在酸性条件下分解制得。","cautions":["二氧化硫刺激呼吸道，在通风处操作。","硫粉尘与空气混合遇火可能爆燃。","废液交实验员按危险废物处理，不要自行用碱液中和或排放。"]},
"iodine":{"apparatus":["试管","分液漏斗","烧杯","蒸发皿"],"observation":"溶液由无色变黄棕，萃取后有机层呈紫色。","conclusion":"碘可由氯气置换碘化物制得，碘在有机溶剂中呈紫色。","cautions":["氯水与四氯化碳均有毒，在通风橱中操作。","碘蒸气刺激眼睛与呼吸道。","废液分类回收，不可倒入下水道。"]},
"red-cabbage-indicator":{"apparatus":["研钵","烧杯","纱布","滴管","白色瓷板"],"observation":"白醋中变红，小苏打水中变蓝绿，肥皂水中变绿。","conclusion":"植物花青素可作酸碱指示剂，颜色随 pH 改变。","cautions":["刀具与热水小心烫伤。","指示剂易变质，冷藏保存并尽快使用。","不可用于食用或医疗判断。"]},
"eggshell-calcium-carbonate":{"apparatus":["研钵","烧杯","漏斗","酒精灯","坩埚"],"observation":"蛋壳粉与盐酸反应冒气泡；灼烧后变为疏松白色固体。","conclusion":"生活废弃物蛋壳可作碳酸钙来源，灼烧可制氧化钙。","cautions":["灼烧时戴护目镜，避免粉尘入眼。","氧化钙遇水放热，勿用手直接接触。","实验用品不可再用于食品。"]},
"baking-soda-ash":{"apparatus":["不锈钢勺","酒精灯","蒸发皿","玻璃棒"],"observation":"加热时产生气体，粉末逐渐结块，质量减轻。","conclusion":"碳酸氢钠热稳定性差，受热分解生成碳酸钠。","cautions":["加热时避免吸入粉尘。","容器烫手，冷却后再取。","产物不可与酸混放，以免剧烈冒泡。"]},
"salt-recrystallization":{"apparatus":["烧杯","玻璃棒","漏斗","滤纸","蒸发皿","酒精灯"],"observation":"滤纸上留下泥沙，滤液蒸发后析出白色立方晶体。","conclusion":"利用溶解度差异，可用溶解—过滤—结晶提纯固体。","cautions":["蒸发时用玻璃棒搅拌，防止液滴飞溅。","不能蒸干至焦糊，出现大量晶体即停止。","实验用盐不可食用。"]},
"copper-acetate":{"apparatus":["烧杯","玻璃棒","蒸发皿","漏斗"],"observation":"铜丝表面产生气泡并逐渐变细，溶液呈蓝绿色。","conclusion":"双氧水把铜氧化，醋酸根与之结合形成可溶的醋酸铜。","cautions":["双氧水会刺激皮肤，佩戴手套。","反应缓慢，勿加热加速以免分解。","醋酸铜有毒，不可入口，废液回收。"]},
"potato-starch":{"apparatus":["擦丝器","纱布","烧杯","玻璃棒"],"observation":"洗出液呈乳白色，静置后底部沉积白色粉末。","conclusion":"利用溶解性差异可从植物中提取淀粉。","cautions":["擦丝器锋利，注意手指。","淀粉受潮易霉变，干燥密封保存。","实验淀粉不可食用。"]},
"orange-limonene":{"apparatus":["广口瓶","研钵","漏斗","滤纸"],"observation":"滤液有浓郁橘香，滴在纸上留下半透明油斑。","conclusion":"有机物易溶于有机溶剂，可用浸提法从植物中提取精油。","cautions":["酒精易燃，远离明火。","柠檬烯对皮肤有轻微刺激。","提取液不可饮用。"]},
"vinegar-rust-removal":{"apparatus":["烧杯","镊子","砂纸","纸巾"],"observation":"溶液逐渐变黄，锈层变松软并脱落，偶有细小气泡。","conclusion":"酸能与金属氧化物反应，可用于除锈，但过量酸会腐蚀铁。","cautions":["白醋对皮肤刺激小，但仍避免入眼。","除锈后立即擦干防再次生锈。","废液交实验员统一处理，不可食用。"]},
"hydrogen-peroxide-oxygen":{"apparatus":["锥形瓶","导管","水槽","集气瓶"],"observation":"混合后迅速产生大量气泡，带火星木条复燃。","conclusion":"过氧化氢在催化剂作用下分解生成氧气，土豆中的酶可起催化作用。","cautions":["双氧水有腐蚀性，勿接触皮肤与眼睛。","氧气助燃，收集时远离明火与油脂。","不可用高浓度双氧水，禁止密闭容器。"]},
"milk-plastic":{"apparatus":["奶锅","纱布","模具","滤网"],"observation":"牛奶结块，滤出的白色固体干燥后变硬。","conclusion":"改变 pH 可使蛋白质沉淀，酪蛋白可加工成可塑材料。","cautions":["加热牛奶注意溢出与烫伤。","成品不可盛装食品。","操作后清洗器具，避免变质发臭。"]},
"sodium-metal":{"apparatus":["电解槽","直流电源","惰性气氛保护装置","集钠器","通风橱"],"observation":"阴极区出现银白色液态钠，阳极有黄绿色氯气产生。","conclusion":"活泼金属只能用电解熔融盐的方法制取；钠的密度小于熔融电解质，便于分离收集。","cautions":["钠遇水剧烈反应并放出氢气，可能燃烧爆炸，严禁接触水、酸和卤代烃。","熔融盐温度高、氯气有毒，仅限工业装置或有资质的实验室演示。","金属钠须浸没在矿物油中密封保存，远离火源。","本条目仅用于原理认知，不提供家庭或非专业场所的操作方案。","网传“氢氧化钠与镁加热到 210 ℃ 制钠”不成立：氢氧化钠熔点约 318 ℃，210 ℃ 时仍是固体；“插入镁条点燃”虽然能提供高温，但燃烧不可控，会伴随氢气、钠蒸气、氧化镁与腐蚀性碱雾，钠分散在熔渣中无法安全收集，不能当作制法。实验室制钠采用电解熔融氯化钠（Downs 法）或电解熔融氢氧化钠（Castner 法）。"]},
"potassium-metal":{"apparatus":["电解槽","直流电源","冷凝收集器","惰性气氛保护装置","通风橱"],"observation":"阴极析出银白色金属，新鲜切面很快变暗；钾在熔盐中部分挥发。","conclusion":"钾比钠更活泼，制备与保存要求更高；工业上也可利用钠的置换反应制钾。","cautions":["钾遇水立即燃烧，甚至发生爆炸，严禁接触水、酸、卤素和卤代烃。","钾与空气接触迅速氧化，须浸没在矿物油或石蜡中密封保存。","电解与冷凝装置复杂、氯气有毒，仅限工业或有资质的实验室。","本条目仅用于原理认知，不提供家庭或非专业场所的操作方案。"]},
"oxygen-electrolysis":{"apparatus":["电解槽","石墨电极两支","直流电源","集气瓶"],"observation":"阳极产生使带火星木条复燃的气体，阴极产生可燃烧的氢气。","conclusion":"水电解生成氢气和氧气，体积比约 2:1；氧气约占空气体积的 21%。","cautions":["电解时远离明火，氢气与氧气混合遇火可能爆鸣。","稀硫酸有腐蚀性，戴护目镜与手套。"]},
"hydrogen-zinc":{"apparatus":["锥形瓶","长颈漏斗","导管","水槽","集气瓶"],"observation":"锌粒表面产生大量气泡，气体可燃，火焰淡蓝色。","conclusion":"活泼金属与稀酸反应放出氢气；点燃前必须验纯。","cautions":["氢气与空气混合遇火会爆鸣，必须验纯。","稀硫酸有腐蚀性。"]},
"carbon-dioxide-vinegar":{"apparatus":["锥形瓶","导管","集气瓶","蜡烛","烧杯"],"observation":"剧烈起泡，气体使澄清石灰水变浑浊，能熄灭蜡烛。","conclusion":"二氧化碳密度比空气大、不支持燃烧；可用石灰水检验。","cautions":["反应容器不要完全密闭，避免气体顶开塞子。","食醋有刺激性。"]},
"copper-oxide-hydroxide":{"apparatus":["蒸发皿","酒精灯","三脚架","泥三角","药匙"],"observation":"蓝色固体逐渐变黑，蒸发皿口有水珠。","conclusion":"难溶性碱受热分解为对应氧化物和水。","cautions":["灼烧时戴护目镜，避免固体飞溅。","氢氧化铜应新制，久置会分解。"]},
"iron-metal-thermite":{"apparatus":["坩埚","铁架台","砂盘","护目镜"],"observation":"剧烈放热，火星四射，生成熔融铁。","conclusion":"铝热反应放出大量热，可用于焊接铁轨和冶炼难熔金属。","cautions":["高危演示：必须在专业实验室、室外或通风橱中由教师操作。","反应温度极高，禁止用水扑救，应使用干砂。","铝粉与氯酸钾混合物受热猛烈，严禁加大用量。"]},
"copper-sulfate-oxide":{"apparatus":["烧杯","玻璃棒","酒精灯","蒸发皿","漏斗"],"observation":"黑色固体溶解，溶液呈蓝色；冷却后析出蓝色晶体。","conclusion":"碱性氧化物与酸反应生成盐和水；胆矾受热失水变白。","cautions":["稀硫酸有腐蚀性。","蒸发浓缩时避免局部过热。"]},
"iodine-kelp":{"apparatus":["烧杯","漏斗","滤纸","分液漏斗","蒸发皿"],"observation":"酸化氧化后溶液呈黄褐色，淀粉试纸变蓝。","conclusion":"海带富含碘元素，碘离子被氧化生成单质碘。","cautions":["碘蒸气有刺激性，操作在通风处进行。","四氯化碳有毒，避免吸入。"]},
"barium-carbonate":{"apparatus":["试管","胶头滴管","漏斗","滤纸"],"observation":"立即产生白色沉淀，滤液澄清。","conclusion":"可溶性钡盐与碳酸盐反应生成难溶的碳酸钡。","cautions":["可溶性钡盐有毒，避免入口和接触伤口。","废液按重金属废液回收。"]},
"zinc-carbonate":{"apparatus":["烧杯","玻璃棒","漏斗","滤纸","烘箱"],"observation":"白色胶状沉淀，洗涤后滤液无白色浑浊。","conclusion":"锌盐与碳酸氢盐反应生成难溶性碱式碳酸锌。","cautions":["避免高温灼烧时吸入粉尘。","废液统一处理。"]},
"lead-sulfide":{"apparatus":["试管","导气管","通风橱"],"observation":"黑色沉淀，滤液呈酸性。","conclusion":"重金属离子与硫化氢生成难溶硫化物，是检验金属离子的方法之一。","cautions":["硫化氢剧毒，必须在通风橱中少量操作。","铅盐有毒且污染环境，废液专门回收。"]},
"copper-i-chloride":{"apparatus":["圆底烧瓶","回流冷凝管","烧杯","布氏漏斗"],"observation":"稀释后出现白色沉淀，暴露空气逐渐变绿。","conclusion":"铜(I)在浓盐酸中以配合物形式稳定，稀释后析出难溶氯化亚铜。","cautions":["浓盐酸挥发刺激，操作在通风橱。","氯化亚铜易被空气氧化，需密封保存。"]},
"potassium-iodate":{"apparatus":["烧杯","酒精灯","蒸发皿","漏斗"],"observation":"碘的棕褐色褪去，得到白色晶体。","conclusion":"卤素在强碱中发生歧化；碘酸钾是加碘盐中的碘来源。","cautions":["氢氧化钾强腐蚀性，戴手套护目镜。","碘蒸气刺激，通风操作。"]},
"manganese-chloride":{"apparatus":["圆底烧瓶","酒精灯","导气管","尾气吸收装置"],"observation":"有黄绿色刺激性气体产生，溶液变为粉红色（水合锰离子）。","conclusion":"浓盐酸被二氧化锰氧化为氯气，锰被还原为二价。","cautions":["氯气剧毒，必须在通风橱中并有尾气吸收。","浓盐酸强腐蚀性。"]},
"chromium-sulfate":{"apparatus":["烧杯","酒精灯","蒸发皿","漏斗"],"observation":"溶液呈紫红色，晶体为紫色。","conclusion":"金属氧化物与酸反应生成盐；Cr(III) 毒性远低于 Cr(VI)。","cautions":["浓硫酸强腐蚀性，避免溅到皮肤。","含铬废液按危废处理，不得排放。"]},
"nickel-sulfate":{"apparatus":["烧杯","酒精灯","蒸发皿","漏斗"],"observation":"绿色溶液，析出绿色晶体。","conclusion":"金属氧化物与酸反应制盐；镍盐溶液呈绿色。","cautions":["镍盐有致敏性，避免皮肤接触。","废液按重金属回收。"]},
"cobalt-chloride":{"apparatus":["烧杯","蒸发皿","漏斗","干燥器"],"observation":"溶液呈粉红色，晶体为粉红色；加热失水变蓝。","conclusion":"水合钴离子呈粉红色，无水氯化钴呈蓝色，可作变色指示。","cautions":["钴盐有潜在致癌性，避免吸入粉尘。","盐酸有腐蚀性。"]},
"sodium-ethoxide":{"apparatus":["圆底烧瓶","干燥管","冰浴","镊子"],"observation":"钠块表面产生气泡，逐渐溶解，溶液变澄清。","conclusion":"乙醇羟基氢被钠置换，生成乙醇钠（强碱）。","cautions":["金属钠遇水剧烈反应，必须使用无水乙醇并远离水。","氢气可燃，避免明火；乙醇钠强腐蚀性。"]},
"calcium-acetate":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿"],"observation":"蛋壳表面持续冒泡，逐渐变软溶解。","conclusion":"碳酸钙与酸反应生成可溶性钙盐；乙酸钙可溶于水。","cautions":["食醋有刺激性，避免溅入眼睛。","加热蒸发时注意防止暴沸。"]},
"ammonium-persulfate":{"apparatus":["电解槽","铂或石墨阳极","铅阴极","直流电源","冰浴"],"observation":"阳极区逐渐出现白色晶体，阴极产生氢气。","conclusion":"电解可将硫酸根氧化为过硫酸根；过硫酸铵是强氧化剂。","cautions":["过硫酸铵强氧化性，避免与可燃物、还原剂混放。","电解产生氢气，远离火源。"]},
"nitric-acid-kno3":{"apparatus":["蒸馏烧瓶","温度计","冷凝管","接收瓶","通风橱"],"observation":"馏出液无色，久置或见光后渐变黄；瓶底残留硫酸氢钾固体。","conclusion":"钠盐和钾盐都只是硝酸根的载体，核心反应相同；钾盐残渣更黏稠，蒸馏结束前不要蒸干。","cautions":["硝酸强腐蚀、强氧化，全程佩戴护目镜和手套。","装置必须气密，尾气用碱液吸收，在通风橱内操作。","不要将硝酸与乙醇等还原性有机物混放。"]},
"hydrochloric-acid-kcl":{"apparatus":["蒸馏烧瓶","滴液漏斗","冷凝管","接收瓶","倒扣漏斗","通风橱"],"observation":"烧瓶内产生白雾，接收瓶液面上升，溶液呈强酸性。","conclusion":"氯化钠与氯化钾都提供氯离子，酸解原理相同；用倒扣漏斗可防止倒吸。","cautions":["氯化氢气体刺激性强，必须在通风橱内操作。","浓硫酸腐蚀性强，滴加时控制速度。","停止加热前先移开导气管，防止吸收液倒吸。"]},
"sodium-carbonate-co2":{"apparatus":["锥形瓶","分液漏斗","导气管","pH 计","蒸发皿","酒精灯"],"observation":"通气过程中溶液温度上升，pH 逐步下降；浓缩后析出白色晶体。","conclusion":"二氧化碳不能过量，否则生成碳酸氢钠；冰水浴可抑制副反应并减少碱雾。","cautions":["氢氧化钠强腐蚀，佩戴护目镜和手套。","二氧化碳通气不宜过快，防止倒吸。","蒸发浓缩时不要蒸干，避免结块和飞溅。"]},
"barium-sulfate-carbonate":{"apparatus":["烧杯","磁力搅拌器","布氏漏斗","抽滤瓶","干燥箱"],"observation":"白色悬浊液逐渐转变成细腻白色沉淀，伴有二氧化碳气泡。","conclusion":"由溶解度更小的硫酸钡取代碳酸钡；必须洗去可溶性钡盐和残酸。","cautions":["可溶性钡盐有毒，禁止入口，操作后洗手。","硫酸有腐蚀性，佩戴护目镜。","废液按含钡废液回收，不可直接排放。"]},
"copper-sulfate-carbonate":{"apparatus":["烧杯","水浴锅","布氏漏斗","蒸发皿","结晶皿"],"observation":"绿色固体溶解，溶液呈蓝色并产生气泡；冷却后析出蓝色晶体。","conclusion":"碱式碳酸铜提供铜离子，硫酸提供硫酸根；浓缩程度决定晶体大小。","cautions":["铜盐有毒，避免入口和粉尘吸入。","稀硫酸有腐蚀性，佩戴护目镜。","含铜废液回收处理。"]},
"calcium-chloride-limestone":{"apparatus":["锥形瓶","分液漏斗","布氏漏斗","蒸发皿","干燥箱"],"observation":"石灰石表面持续冒出气泡并逐渐溶解，滤液无色。","conclusion":"盐酸过量可保证石灰石反应完全，再用碳酸钙回调 pH，避免产品显酸性。","cautions":["稀盐酸仍有腐蚀性，避免溅入眼睛。","二氧化碳大量产生，保持通风，不要密闭。","无水氯化钙水合放热明显，干燥时注意散热。"]},
"ammonium-chloride-sulfate":{"apparatus":["烧杯","布氏漏斗","蒸发皿","pH 试纸"],"observation":"混合后出现白色细沉淀；滤液浓缩后析出针状或粒状晶体。","conclusion":"利用硫酸钙微溶实现离子分离；若硫酸根过量，可补加少量氯化钙再过滤。","cautions":["氯化钡有毒，检验时只用滴管取少量滤液。","铵盐受热易分解，干燥温度不超过 80 ℃。","废液集中处理。"]},
"potassium-nitrate-koh":{"apparatus":["烧杯","滴管","pH 计","蒸发皿","结晶皿"],"observation":"中和时放热，溶液保持无色；浓缩后析出白色晶体。","conclusion":"强碱强酸盐溶液近中性；终点控制在 pH 7 附近，避免硝酸过量。","cautions":["氢氧化钾强腐蚀，佩戴护目镜和手套。","硝酸有氧化性，避免与有机物接触。","硝酸钾是强氧化剂，禁止与还原剂研磨混合。"]},
"nickel-chloride":{"apparatus":["烧杯","磁力搅拌器","漏斗","蒸发皿","结晶皿"],"observation":"黑色氧化镍溶解，溶液呈绿色；冷却后析出绿色晶体。","conclusion":"碱性氧化物与酸反应生成盐，镍离子进入溶液后结晶。","cautions":["镍盐有毒并可能致敏，戴手套操作，避免粉尘。","盐酸腐蚀性，避免飞溅。","含镍废液按重金属废物回收。"]},
"cobalt-sulfate":{"apparatus":["烧杯","加热板","漏斗","蒸发皿","结晶皿"],"observation":"黑色固体溶解，溶液呈粉红色；冷却后析出红色晶体。","conclusion":"金属氧化物与酸反应生成可溶性盐。","cautions":["钴盐有毒且可能致敏，戴手套与护目镜。","加热酸液注意酸雾，通风操作。","含钴废液单独回收。"]},
"strontium-chloride":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","结晶皿"],"observation":"固体溶解并产生气泡，溶液无色；冷却后析出无色晶体。","conclusion":"碳酸盐与酸反应生成可溶性盐、水和二氧化碳。","cautions":["盐酸腐蚀性，戴护目镜。","反应产生二氧化碳，避免密闭。","废液交实验员按危险废物处理，不要自行中和或排放。"]},
"strontium-nitrate":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","结晶皿"],"observation":"固体溶解并冒气泡，溶液无色；冷却析出无色晶体。","conclusion":"碳酸盐与硝酸反应生成硝酸盐、二氧化碳和水。","cautions":["硝酸腐蚀性与氧化性，避免接触皮肤和还原剂。","硝酸锶是氧化剂，远离糖、硫和金属粉末。","废液分类回收。"]},
"lithium-sulfate":{"apparatus":["烧杯","加热板","漏斗","蒸发皿","结晶皿"],"observation":"固体溶解并产生气泡，溶液无色；浓缩后析出无色晶体。","conclusion":"碳酸盐与酸反应生成可溶性硫酸盐。","cautions":["稀硫酸腐蚀性，戴护目镜。","蒸发浓缩防暴沸。","废液交实验员按危险废物处理，不要自行中和或排放。"]},
"sodium-bromide":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","结晶皿"],"observation":"加酸时产生气泡，溶液无色；浓缩后析出白色晶体。","conclusion":"碳酸盐与酸中和生成溴化钠、二氧化碳和水。","cautions":["氢溴酸腐蚀性，通风操作。","溴化钠见光易氧化，产品避光密封。","废液交实验员按危险废物处理，不要自行中和或排放。"]},
"calcium-bromide":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","结晶皿"],"observation":"固体溶解并产生气泡，溶液无色；浓缩后析出白色晶体。","conclusion":"碳酸盐与酸反应生成可溶性钙盐。","cautions":["氢溴酸腐蚀性，戴护目镜。","浓缩时避免蒸干。","废液交实验员按危险废物处理，不要自行中和或排放。"]},
"magnesium-phosphate":{"apparatus":["烧杯","磁力搅拌器","pH 试纸","抽滤装置","干燥箱"],"observation":"悬浊液逐渐变稠，抽滤得到白色沉淀。","conclusion":"氧化镁与磷酸反应生成难溶磷酸镁。","cautions":["磷酸腐蚀性，戴护目镜。","沉淀洗涤要彻底，避免残留酸。","废液交实验员按危险废物处理，不要自行中和或排放。"]},
"aluminium-nitrate":{"apparatus":["烧杯","水浴","漏斗","蒸发皿","结晶皿"],"observation":"白色胶状固体溶解，溶液无色；冷却析出无色晶体。","conclusion":"两性氢氧化物与酸反应生成铝盐。","cautions":["硝酸腐蚀性与氧化性，避免与还原剂接触。","氢氧化铝胶状物过滤较慢，可静置后过滤。","废液分类回收。"]},
"sodium-oxalate":{"apparatus":["烧杯","加热板","漏斗","蒸发皿","结晶皿"],"observation":"加酸产生气泡，溶液无色；浓缩析出白色晶体。","conclusion":"碳酸盐与二元酸中和生成草酸盐。","cautions":["草酸及草酸盐有毒，避免入口和吸入粉尘。","不要与高锰酸钾等氧化剂随意混合。","废液按含草酸盐废物回收。"]},
"tin-chloride":{"apparatus":["圆底烧瓶","回流冷凝管","水浴","蒸发皿","结晶皿"],"observation":"锡粒表面产生气泡并逐渐溶解，溶液无色；冷却析出白色晶体。","conclusion":"锡与浓盐酸反应生成氯化亚锡和氢气。","cautions":["浓盐酸腐蚀性强，氢气可燃，全程通风并远离火源。","氯化亚锡易水解和氧化，配制溶液时需加盐酸。","含锡废液回收。"]},
"copper-iodide":{"apparatus":["烧杯","磁力搅拌器","抽滤装置","干燥箱"],"observation":"混合后出现白色沉淀并伴随黄色碘；加亚硫酸钠后黄色消失，沉淀保持白色。","conclusion":"铜(II)被碘离子还原为铜(I)，生成难溶碘化亚铜；亚硫酸钠把生成的碘还原回碘离子。","cautions":["铜盐与碘化物有毒，戴手套操作。","亚硫酸钠避免与酸混合，防止释放二氧化硫。","含铜、碘废液分类回收。"]},
"sodium-carbonate-baking":{"apparatus":["耐热瓷皿或不锈钢盘","烤箱或电炉","玻璃棒","干燥密封罐"],"observation":"白色粉末逐渐结块、质量减少；加醋仍会冒泡，但比原来弱。","conclusion":"碳酸氢钠受热分解生成碳酸钠、水和二氧化碳；家庭加热难以完全转化。","cautions":["高温容器烫手，取放时戴隔热手套。","避免吸入粉末，操作后洗手。","产物可能仍含小苏打，不能当作试剂级纯碱或食品添加剂使用。","不要与含氯清洁剂混合使用。"]},
"sodium-acetate-vinegar":{"apparatus":["烧杯或玻璃碗","玻璃棒","漏斗与滤纸","蒸发皿","电炉"],"observation":"加入小苏打后大量气泡，液面下降；浓缩冷却后析出白色晶体。","conclusion":"乙酸与碳酸氢钠发生中和并放出二氧化碳，生成可溶的乙酸钠。","cautions":["食醋有刺激性，避免溅入眼睛。","加小苏打要慢，泡沫可能溢出。","蒸发时保持通风，防止暴沸。","产物纯度有限，不可食用或当作试剂。"]},
"calcium-chloride-cleaner":{"apparatus":["塑料杯","玻璃棒","漏斗与滤纸","蒸发皿","护目镜","耐酸手套"],"observation":"蛋壳表面剧烈冒泡并逐渐溶解，溶液先浑浊后澄清。","conclusion":"碳酸钙与盐酸反应生成可溶性氯化钙、水和二氧化碳。","cautions":["洁厕灵含盐酸，腐蚀性强；必须戴护目镜和耐酸手套，避免溅到皮肤和眼睛。","严禁与 84 消毒液、漂白粉、含氯清洁剂混合——会释放有毒氯气。","只在通风处操作；闻到刺激性气味立即停止并离开。","产物含表面活性剂等杂质，不可食用、不可用于食品或伤口处理。"]},
"calcium-hydroxide-quicklime":{"apparatus":["耐热烧杯","玻璃棒","塑料漏斗与滤纸","护目镜","手套"],"observation":"剧烈放热、冒蒸汽，白色块状物崩解成粉末；悬浊液使酚酞变红。","conclusion":"生石灰与水化合生成氢氧化钙，反应放出大量热。","cautions":["反应剧烈放热，可能沸腾飞溅；必须戴护目镜和手套，分次少量加水。","氢氧化钙有腐蚀性，避免接触皮肤和眼睛。","不要使用铝制容器。","密封保存，防止与二氧化碳反应变质。"]},
"sodium-citrate-cleaner":{"apparatus":["烧杯","玻璃棒","漏斗与滤纸","蒸发皿","电炉","pH 试纸"],"observation":"加入小苏打后持续冒泡，酸味减弱；浓缩后析出白色晶体。","conclusion":"三元弱酸与碳酸氢钠中和生成柠檬酸钠、水和二氧化碳。","cautions":["除垢剂可能含其他酸，戴手套和护目镜。","加小苏打要慢，防止泡沫溢出。","产物不可食用，不可代替食品级柠檬酸钠。"]},
"citric-acid-solution":{"apparatus":["烧杯","量筒","玻璃棒","试剂瓶","pH 试纸"],"observation":"固体迅速溶解，溶液 pH 约 2；接触水垢后缓慢冒出细小气泡。","conclusion":"配制得到约 0.5 mol/L 的柠檬酸溶液；弱酸除垢比强酸温和。","cautions":["柠檬酸粉末刺激眼睛和呼吸道，戴护目镜。","不要与含氯漂白剂混用。","贴好标签，避免误食。"]},
"sulfuric-acid-oxalate":{"apparatus":["烧杯","玻璃棒","漏斗与滤纸","锥形瓶","防护眼镜与丁腈手套","通风处或通风橱"],"observation":"混合后出现蓝绿色沉淀；滤液呈明显酸性，pH 通常在 1–3 之间。","conclusion":"沉淀转化可以把硫酸根从可溶铜盐转移到溶液中，但产物是浓度较低的稀硫酸且含铜杂质；浓缩、提纯需要专业设备，不能在家完成。","cautions":["草酸有毒且有腐蚀性，避免吸入粉尘、接触皮肤和眼睛；必须戴护目镜与丁腈手套。","本方法只能得到稀硫酸；不要加热浓缩，浓缩会带出草酸和铜盐，并产生酸雾与喷溅风险。","含铜废液不得倒入下水道，应交给学校实验室或危险废物回收点处理。","本条目仅用于理解沉淀转化与酸制备原理，不构成家庭操作方案。"]},
"sodium-chlorate":{"apparatus":["蒸发皿","水浴锅","温度计","玻璃棒","布氏漏斗","抽滤瓶","结晶皿"],"observation":"加热时有轻微氯味，溶液逐渐变稠；冷却后析出白色针状或片状晶体。","conclusion":"次氯酸钠在加热浓缩条件下发生歧化，生成氯酸钠和氯化钠；利用溶解度差异结晶分离。","cautions":["氯酸钠是强氧化剂，与有机物、硫、磷、金属粉末混合后摩擦或受热可能燃烧甚至爆炸，必须单独存放。","加热时可能逸出氯气，必须在通风橱或强通风处操作，避免吸入。","不要蒸干或高温烘烤，残液和晶体都不要带回家或用于杂草、烟花等用途。","含氯酸盐废液按危险废物处理，不能直接倒入下水道。"]},
"sodium-perchlorate":{"apparatus":["直流电源","惰性阳极（铂或镀铂钛）","铁或镍阴极","带隔膜的电解槽","温度计","蒸发皿","结晶皿","布氏漏斗"],"observation":"阴极持续产生气泡（氢气），阳极区氯酸钠逐渐转化为高氯酸钠；浓缩冷却后析出白色晶体。","conclusion":"电解把氯酸根在阳极进一步氧化为高氯酸根，钠离子保持不变，结晶得到高氯酸钠。","cautions":["高氯酸钠是强氧化剂，与有机物、还原剂、金属粉末混合后摩擦、撞击或受热可能燃烧或爆炸，必须单独、阴凉、避光保存。","电解会产生氢气，必须远离火源并保持通风；电解槽不能密闭。","不要向氯酸钠电解液中加酸：酸化可能生成二氧化氯等危险气体；电解液保持中性或弱碱性。","不要蒸干、研磨或高温干燥产物；不要用于烟花、推进剂或任何自制含能材料。","高氯酸盐在环境中难降解，废液与残渣按危险废物回收，不能排入下水道。"]},
"sodium-bisulfite":{"apparatus":["锥形瓶","分液漏斗","导气管","烧杯","冰水浴","布氏漏斗"],"observation":"碱液吸收二氧化硫后先变浑浊，继续通气又逐渐澄清；冷却后析出白色晶体。","conclusion":"二氧化硫是酸性氧化物，被碱吸收生成酸式盐；控制二氧化硫过量程度可得到亚硫酸氢钠。","cautions":["二氧化硫有强烈刺激性，必须通风橱操作，避免吸入。","亚硫酸氢钠对皮肤和眼睛有刺激性，戴手套与护目镜。","含亚硫酸盐废液不能直接排放，按实验室废液处理。"]},
"potassium-nitrite":{"apparatus":["坩埚","马弗炉","玻璃棒","烧杯","蒸发皿","抽滤装置"],"observation":"硝酸钾熔化并放出无色气体，冷却后得到白色固体；溶于水后溶液呈弱碱性。","conclusion":"硝酸盐高温分解可失去部分氧，生成亚硝酸盐；产物中氮的氧化数由 +5 降到 +3。","cautions":["硝酸钾和亚硝酸钾都是强氧化剂，不能与有机物、硫、磷、金属粉末混放或研磨。","亚硝酸盐有毒并可能生成亚硝胺，严禁入口，操作后彻底洗手。","高温分解可能产生氮氧化物，必须在通风橱或专用高温炉中进行。"]},
"cobalt-nitrate":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","结晶皿"],"observation":"碳酸钴溶解并放出二氧化碳，溶液呈红色；冷却后析出红色晶体。","conclusion":"碳酸盐与酸反应生成可溶性盐、二氧化碳和水；钴离子在水溶液中呈红色。","cautions":["钴盐有毒并可能引起过敏，避免粉尘与皮肤接触。","硝酸有腐蚀性，操作时戴手套与护目镜。","含钴废液按重金属废物回收，不能排入下水道。"]},
"nickel-nitrate":{"apparatus":["烧杯","磁力搅拌器","漏斗","蒸发皿","结晶皿"],"observation":"黑色氧化镍溶解，溶液呈绿色；冷却后析出绿色晶体。","conclusion":"碱性氧化物与酸反应生成盐和水；镍离子进入溶液后结晶。","cautions":["镍盐有毒并可能致敏，戴手套操作，避免粉尘。","硝酸腐蚀性，避免飞溅。","含镍废液按重金属废物回收。"]},
"copper-bromide":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","干燥器"],"observation":"黑色氧化铜溶解，溶液呈棕绿色；浓缩冷却后析出棕黑色晶体。","conclusion":"碱性氧化物与氢溴酸反应生成溴化铜和水；铜(II)的溴化物颜色较深且易潮解。","cautions":["氢溴酸有腐蚀性，操作时戴手套与护目镜。","溴化铜易潮解并可能刺激皮肤，密封保存。","含铜废液按重金属废物回收。"]},
"calcium-iodide":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","棕色瓶"],"observation":"碳酸钙溶解并放出二氧化碳，溶液无色；冷却后析出无色晶体。","conclusion":"碳酸盐与酸反应生成盐、二氧化碳和水；碘化钙易溶于水，结晶水合物需避光保存。","cautions":["氢碘酸有强腐蚀性，操作时戴手套与护目镜。","碘化物见光或接触氧化剂会析出碘，必须避光密封。","含碘废液按实验室废液处理。"]},
"zinc-iodide":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","棕色瓶"],"observation":"白色氧化锌溶解，溶液无色；浓缩冷却后析出白色晶体。","conclusion":"两性氧化物与氢碘酸反应生成碘化锌和水；锌离子与碘离子形成可溶性盐。","cautions":["氢碘酸有腐蚀性，戴手套与护目镜。","碘化锌易潮解并见光变色，必须密封避光保存。","含锌废液按实验室废液处理。"]},
"potassium-bromate":{"apparatus":["三口烧瓶","导气管","冰水浴","布氏漏斗","结晶皿"],"observation":"溶液先变黄，继续通气后颜色变浅；冷却后析出白色溴酸钾晶体。","conclusion":"碱性条件下氯气把溴离子氧化为溴酸根；钾离子与溴酸根形成溶解度较小的溴酸钾。","cautions":["溴酸钾是强氧化剂且被列为可能致癌物，避免粉尘、严禁入口。","氯气有毒，必须在通风橱内现制现用，尾气要用碱液吸收。","不要与有机物、硫、磷、金属粉末混合或研磨，避免燃烧爆炸。","含溴酸盐废液按危险废物处理。"]},
"benzyl-benzoate":{"apparatus":["圆底烧瓶","分水器","回流冷凝管","分液漏斗","减压蒸馏装置"],"observation":"回流时体系逐渐澄清，分水器中收集到水；产物为无色油状液体。","conclusion":"羧酸与醇在酸催化下发生可逆酯化；移除水使平衡向酯的方向移动。","cautions":["浓硫酸有强腐蚀性，加入时缓慢并摇匀。","苯甲醇与苯甲酸对皮肤有刺激性，避免长时间接触。","减压蒸馏需要防爆屏与规范装置，不能密闭加热。"]},
"ethyl-cinnamate":{"apparatus":["圆底烧瓶","回流冷凝管","分液漏斗","蒸馏装置"],"observation":"回流后体系有肉桂香气；碱洗时水相呈碱性，有机相分层。","conclusion":"肉桂酸与乙醇在酸催化下生成酯；乙醇过量有利于提高酯的产率。","cautions":["浓硫酸有强腐蚀性，操作时戴手套与护目镜。","乙醇易燃，蒸馏时不能明火直接加热，注意通风。","酯类产物对皮肤有轻微刺激性，避免入口。"]},
"triacetin":{"apparatus":["圆底烧瓶","分水器","回流冷凝管","分液漏斗","减压蒸馏装置"],"observation":"回流过程中分水器收集到水，体系逐渐变稠；产物为无色油状液体。","conclusion":"多元醇与过量羧酸在酸催化下可生成三酯；及时移除水提高酯化程度。","cautions":["浓硫酸与冰乙酸都有腐蚀性，避免飞溅。","甘油高温可能分解产生刺激性气体，控制温度。","减压蒸馏需规范装置，不能密闭加热。"]},
"benzyl-acetate":{"apparatus":["圆底烧瓶","分水器","回流冷凝管","分液漏斗","蒸馏装置"],"observation":"回流时体系逐渐澄清并分出水分；产物有茉莉样香气。","conclusion":"羧酸与醇在酸催化下生成酯；带水剂移除水使平衡向产物移动。","cautions":["浓硫酸有强腐蚀性，冰乙酸有刺激性，注意防护。","苯甲醇对皮肤有刺激性，避免长时间接触。","蒸馏时注意通风，避免吸入蒸气。"]},
"magnesium-citrate":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","结晶皿"],"observation":"氧化镁溶解，溶液呈弱酸性；浓缩冷却后析出白色晶体。","conclusion":"碱性氧化物与羧酸反应生成羧酸盐；柠檬酸三镁可溶于水并结晶。","cautions":["柠檬酸有刺激性，避免入眼。","镁盐过量摄入会引起腹泻，产物不能当保健品随意服用。","结晶母液可回收，不要直接排放。"]},
"potassium-sodium-tartrate":{"apparatus":["烧杯","pH 试纸","漏斗","蒸发皿","结晶皿"],"observation":"酒石酸氢钾溶解后加入碱，溶液保持澄清；冷却后析出无色晶体。","conclusion":"酸式盐与碱发生中和反应生成正盐；酒石酸钾钠以四水合物形式结晶。","cautions":["氢氧化钠有腐蚀性，戴手套与护目镜。","稀释或中和会放热，必须由实验员操作，缓慢加入并搅拌。","产物用于斐林试剂等实验，不可食用。"]},
"sodium-ammonium-phosphate":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","结晶皿"],"observation":"两种盐溶解后溶液澄清；冷却后析出无色晶体。","conclusion":"复分解反应生成溶解度较小的磷酸氢钠铵，冷却结晶实现分离。","cautions":["氯化铵受热分解产生氨与氯化氢，避免高温干烧。","磷酸盐废液可能导致水体富营养化，按实验室废液处理。","产物不可食用。"]},
"iron-bromide":{"apparatus":["锥形瓶","漏斗","蒸发皿","结晶皿","棕色瓶"],"observation":"铁屑溶解并放出氢气，溶液呈浅绿色；冷却后析出浅绿色晶体。","conclusion":"铁与氢溴酸发生置换反应生成亚铁盐和氢气；铁过量避免亚铁被氧化。","cautions":["氢溴酸有腐蚀性，操作时戴手套与护目镜。","反应产生氢气，必须远离火源并保持通风。","亚铁盐易被空气氧化，产物应避光密封并尽快使用。"]},
"magnesium-bromide":{"apparatus":["烧杯","玻璃棒","漏斗","蒸发皿","干燥器"],"observation":"白色氧化镁溶解，溶液无色；冷却后析出无色晶体。","conclusion":"碱性氧化物与氢溴酸反应生成溴化镁和水；镁盐结晶水合物易潮解。","cautions":["氢溴酸有腐蚀性，戴手套与护目镜。","溴化镁易潮解，密封保存。","含镁废液按实验室废液回收，由实验员处理。"]},
"sodium-pyrophosphate":{"apparatus":["坩埚","马弗炉","烧杯","漏斗","结晶皿"],"observation":"加热时固体逐渐熔融并放出水蒸气；冷却后得到白色块状固体。","conclusion":"酸式磷酸盐高温缩合脱去水，形成焦磷酸盐；两个磷酸根通过氧桥连接。","cautions":["高温炉操作戴隔热手套，避免烫伤。","焦磷酸盐废液含磷，按实验室废液处理，避免水体富营养化。","产物不可食用。"]},
"lithium-nitrate":{"apparatus":["烧杯","蒸发皿","抽滤装置","干燥器"],"observation":"无色晶体，强吸湿性。","conclusion":"硝酸锂由碳酸锂与硝酸反应制得。","cautions":["硝酸腐蚀，戴护目镜。","产物易潮解，密封保存。"]},
"ferrous-nitrate":{"apparatus":["烧杯","抽滤装置","蒸发皿","干燥器"],"observation":"浅绿色晶体，久置表面变黄。","conclusion":"复分解法可制得硝酸亚铁，关键是防止 Fe²⁺ 氧化。","cautions":["硝酸钡有毒，废液回收。","产物易氧化，密封避光保存。"]},
"ferric-nitrate":{"apparatus":["烧杯","水浴","蒸发皿","抽滤装置"],"observation":"淡紫色至灰白色晶体，易潮解。","conclusion":"硝酸铁可由氧化铁与硝酸直接反应制得。","cautions":["硝酸腐蚀，通风处操作。","产物吸湿并缓慢水解，密封保存。"]},
"manganese-nitrate":{"apparatus":["烧杯","蒸发皿","抽滤装置","干燥器"],"observation":"淡粉色晶体，易潮解。","conclusion":"硝酸锰由碳酸锰与硝酸中和制得。","cautions":["锰盐有毒，避免吸入粉尘。","硝酸锰是强氧化剂，远离有机物与还原剂。"]},
"chromium-nitrate":{"apparatus":["烧杯","水浴","蒸发皿","抽滤装置"],"observation":"紫色晶体，易潮解。","conclusion":"硝酸铬由氢氧化铬与硝酸反应制得。","cautions":["铬盐有毒，避免接触皮肤与吸入。","强氧化条件下可能生成 Cr(VI)，废液按重金属处理。"]},
"strontium-sulfate":{"apparatus":["烧杯","抽滤装置","烘箱","天平"],"observation":"白色细晶沉淀。","conclusion":"硫酸锶可由可溶性锶盐与硫酸盐复分解制得。","cautions":["锶盐避免误食。","洗涤滤液合并处理。"]},
"silver-sulfate":{"apparatus":["烧杯","抽滤装置","棕色瓶","烘箱"],"observation":"白色至灰白色沉淀，见光变暗。","conclusion":"硫酸银由银盐与硫酸盐复分解制得。","cautions":["银盐成本高且对水生生物有毒，废液回收银。","产物避光保存，避免与还原剂接触。"]},
"lead-sulfate":{"apparatus":["烧杯","抽滤装置","烘箱","天平"],"observation":"白色重质沉淀。","conclusion":"硫酸铅可由可溶性铅盐与硫酸盐复分解制得。","cautions":["铅盐有毒且可在体内蓄积，戴手套，废液按危废处理。","禁止加热分解或随意丢弃。"]},
"tin-sulfate":{"apparatus":["锥形瓶","水浴","蒸发皿","抽滤装置"],"observation":"无色至浅黄色晶体，易氧化。","conclusion":"硫酸亚锡由锡与稀硫酸反应制得。","cautions":["氢气易燃，远离火源。","Sn²⁺ 易氧化，产物密封并加锡屑保存。"]},
"strontium-carbonate":{"apparatus":["烧杯","抽滤装置","烘箱","天平"],"observation":"白色沉淀，加稀盐酸冒泡。","conclusion":"碳酸锶由可溶性锶盐与碳酸盐复分解制得。","cautions":["锶盐避免误食。","洗涤水合并处理。"]},
"manganese-carbonate":{"apparatus":["烧杯","抽滤装置","烘箱","天平"],"observation":"淡粉色沉淀，久置氧化变褐。","conclusion":"碳酸锰由锰盐与碳酸盐复分解制得。","cautions":["锰盐有毒，避免吸入。","产物避免高温，防止氧化。"]},
"ferrous-carbonate":{"apparatus":["烧杯","抽滤装置","干燥器","氮气或油封"],"observation":"灰绿色沉淀，暴露空气后变褐。","conclusion":"碳酸亚铁由亚铁盐与碳酸氢盐反应制得。","cautions":["产物极易氧化，操作尽量隔绝空气。","废液含铁与硫酸盐，集中处理。"]},
"lead-carbonate":{"apparatus":["烧杯","抽滤装置","烘箱","天平"],"observation":"白色重质沉淀。","conclusion":"碳酸铅由可溶性铅盐与碳酸盐复分解制得。","cautions":["铅盐有毒，戴手套，避免粉尘。","废液与滤纸按含铅危废处理。"]},
"silver-carbonate":{"apparatus":["棕色烧杯","抽滤装置","干燥器","护目镜"],"observation":"淡黄色沉淀，见光逐渐变暗。","conclusion":"碳酸银由银盐与碳酸盐复分解制得。","cautions":["产物不稳定，干燥或受热可能分解，禁止研磨、加热或大量制备。","银盐对水生生物有毒，废液回收银。","仅限教师少量演示。"]},
"cobalt-carbonate":{"apparatus":["烧杯","抽滤装置","烘箱","天平"],"observation":"粉红色沉淀。","conclusion":"碳酸钴由钴盐与碳酸盐复分解制得。","cautions":["钴盐有毒并可能致敏，戴手套。","废液按重金属处理。"]},
"zinc-hydroxide":{"apparatus":["试管 ×3","试管架","胶头滴管","烧杯（废液）"],"observation":"第 1 支出现白色胶状沉淀，振荡后不消失；第 2 支沉淀逐渐溶解成无色澄清溶液；第 3 支沉淀也溶解，但没有气泡。","conclusion":"氢氧化锌既能被强酸溶解，也能被过量强碱溶解，属于两性氢氧化物。","cautions":["氢氧化钠有腐蚀性，戴护目镜与手套。","沉淀较细，静置后取上层清液观察更清楚。","含锌废液不要倒入下水道，交实验员统一处理。"]},
"sodium-stearate":{"apparatus":["圆底烧瓶","回流冷凝管","水浴锅","蒸发皿","抽滤装置"],"observation":"回流过程中溶液逐渐变稠；蒸去乙醇后冷却得到白色蜡状固体，遇水可形成乳浊液。","conclusion":"硬脂酸钠是阴离子表面活性剂，分子一端亲水、一端亲油，能把油污分散到水中。","cautions":["乙醇易燃，回流装置必须远离明火并保持通畅。","氢氧化钠溶液有腐蚀性，戴手套与护目镜。","回流时不要密闭体系，防止压力升高。"]},
"glycine":{"apparatus":["圆底烧瓶","水浴锅","蒸发皿","抽滤装置","pH 试纸"],"observation":"反应液逐渐由酸性变为碱性，浓缩后出现白色晶体，溶于水后呈两性。","conclusion":"卤代酸与过量氨的氨解是制备氨基酸的经典路线，副产物氯化铵可用乙醇沉淀除去。","cautions":["一氯乙酸有腐蚀性和毒性，必须在通风橱内称量。","浓氨水有强烈刺激性，加料时不要俯身正对瓶口。","任何试剂都不得品尝；产物仅作教学样品。"]},
"anhydrous-copper-sulfate":{"apparatus":["坩埚","泥三角","酒精灯或电炉","干燥器","电子天平"],"observation":"蓝色晶体先变成浅蓝，再变成白色粉末，坩埚上方有水雾；白色固体遇水滴立刻变回蓝色。","conclusion":"结晶水的失去是可逆的，无水硫酸铜遇水生成蓝色的五水合物，可用于检验微量水。","cautions":["高温加热时可能有少量 SO₃ 逸出，需在通风处进行。","无水物极易吸潮，冷却后应立即放入干燥器并密封保存。","铜盐有毒，废液与残渣交实验员按含铜废液处理。"]},
"borax":{"apparatus":["蒸发皿","坩埚（熔融用）","烧杯","结晶皿","抽滤装置"],"observation":"熔融时放出气体，熔块呈玻璃状；冷却结晶得到无色半透明晶体。","conclusion":"硼酸是弱酸，与碳酸钠反应生成四硼酸钠；十水合物在热水中溶解度较大，冷却即可结晶。","cautions":["熔融在高温下进行，使用坩埚与隔热手套，避免烫伤。","硼砂不宜入口，实验后洗手。","结晶母液不要倒入下水道，交实验员处理。"]},
"potassium-thiocyanate":{"apparatus":["烧杯","玻璃棒","容量瓶（500 mL）","电子天平","棕色试剂瓶"],"observation":"溶液无色；加入含 Fe³⁺ 的溶液后立即变为血红色。","conclusion":"硫氰化钾是检验 Fe³⁺ 的灵敏试剂，常用于铁的比色与定性分析。","cautions":["硫氰酸盐遇酸可能放出有毒气体，不要与酸长期混合或加热。","试剂应避光保存，浓度标签要写清楚。","实验废液含金属离子，交实验员处理。"]},
"potassium-ferrocyanide":{"apparatus":["烧杯","玻璃棒","容量瓶（250 mL）","药匙","滴管"],"observation":"溶液淡黄色；加入 Fe³⁺ 后立即生成深蓝色沉淀，颜色极深。","conclusion":"亚铁氰化钾是检验 Fe³⁺ 的特征试剂，普鲁士蓝为一种配位化合物。","cautions":["遇强酸或高温可能分解放出剧毒的氰化氢，必须避免与酸共热。","试剂只在通风处、小量使用，废液交实验员按含氰废液封存处理。","不要把试剂带出实验室或用于非教学用途。"]},
"potassium-ferricyanide":{"apparatus":["烧杯","玻璃棒","容量瓶（250 mL）","棕色瓶","滴管"],"observation":"溶液橙红色；加入 Fe²⁺ 后生成深蓝色沉淀，颜色与普鲁士蓝近似。","conclusion":"铁氰化钾用于检验 Fe²⁺，与亚铁氰化钾共同构成铁离子的特征检验对。","cautions":["本试剂遇酸或受热会放出剧毒氰化氢，只能由教师少量配制并在通风橱内操作。","严禁与酸、氧化剂混放；废液单独收集、当天交实验员封存处理。","皮肤接触后立即用大量清水冲洗并就医。"]},
"sodium-nitrite":{"apparatus":["铁坩埚","泥三角","酒精灯","试管","表面皿"],"observation":"熔融时缓慢放出气体；溶液加酸后试纸变蓝，说明生成了氧化性的亚硝酸（同时放出 NO）。","conclusion":"亚硝酸钠在酸性条件下表现明显的氧化性，能使碘离子氧化生成碘。","cautions":["亚硝酸钠外观像食盐，剧毒且易误食，必须单独贴红色标签、锁柜保管。","受热可能分解产生有毒氮氧化物，加热必须在通风处进行。","严禁与食品、餐具同处；实验后立即洗手，废液交实验员单独处理。"]},
"calcium-bicarbonate":{"apparatus":["试管","导气管","酒精灯","试管夹"],"observation":"先出现白色沉淀，继续通入气体后沉淀溶解；加热后溶液再次变浑浊。","conclusion":"碳酸氢钙可溶而碳酸钙难溶，二者随二氧化碳的溶解与加热互相转化，这是暂时硬度与锅垢形成的原因。","cautions":["石灰水有腐蚀性，避免接触皮肤与眼睛。","现制的二氧化碳要经过水洗除去酸雾。","加热试管时管口不要对着人。"]}
};
